INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5FS9F0H2EKDTHEPKDE', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.69.0', 'Reclaim', 'shipped', '2026-08-15', '2026-08-14', 'Reclaimed the ~11 GB the vector store had leaked to orphaned embeddings, then re-embedded what was missing. #250 vector bloat — reclaim + backfill + re-embed. Root cause already fixed in PR #249.', NULL, 'ref-01M0V6SS5FVXHZCQJCER3V8TCG', NULL, 'https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/250', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5FEQMK5FVTZHR7KPRR', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.70.0', 'Green Board', 'draft', '2026-09-15', NULL, 'The first release a stranger can clone and succeed with — published to a new public repository under its own organization, with install, onboarding and secret-scanning proven rather than assumed. #66 release-gate tracker (front-door, shakedown, TruffleHog), #67 working-directory-dependent tests. Both carry forward work the retiring repo tracked as #276 and #255; its #275, #273 and #242 were re-verified against this tree on 2026-08-18 and are already fixed here, and #178/#225 are confirmed stale — evidence in #66. 3-Eyes excluded by operator decision as diagnostics rather than core. Scope QA''d by cross-model relay 2026-08-15 (Approved r5), remap QA''d 2026-08-18.', NULL, 'ref-01M0V6SS5FGGBXYFHPA08MMWCH', NULL, 'https://github.com/HiQS-Suite/rebalanceOS/issues/66', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GPFMAANZG4GYFAV4X', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.71.0', 'Subtraction', 'draft', '2026-10-15', NULL, 'Deletes rather than adds — removes surfaces, renderers and models the product no longer earns, measured as net negative lines. #271 subtraction pass (C1-C8) — absorbs the open GH-266 Phase 4 remnants (stale MCP docs, weakened assertion, TF-IDF keyset pagination). Run as a marathon; plan and per-lane contracts in PROJECT/2-WORKING/GH-271-SUBTRACTION/.', NULL, 'ref-01M0V6SS5GPZBJE67W056VBQG6', NULL, 'https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/271', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GE588Z6MNRK6X4Y6H', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.72.0', 'Daily Driver', 'draft', '2026-11-15', NULL, 'Proves the product survives a week of real daily use on one machine without intervention; no new features, only evidence. Proof, not new work — consolidates the former 0.71.0 Daily Driver and 0.72.0 Punch List into one milestone. Prerequisites: #216 MLX instrumentation, #217 MLX memory cap. Regression gates only: #209, #210, #213, #215, #222 (closed).', NULL, 'ref-01M0V6SS5GQ0060QJRJVQWMHHE', NULL, 'https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/266', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GENN684JS0F3CFE7X', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.73.0', 'Subsystem Unification', 'shipped', '2026-12-15', '2026-08-17', 'Foundational test isolation and DRY infrastructure consolidation across collectors and libraries. #7 HiQS test process isolation, #25 time_ops timestamp consolidation, #26 GitHubClient routing, #27 database persistence/upsert deduplication, #28 git_ops subprocess wrapper, #30 dead code and stale doc cleanup. Shipped ahead of 0.70.0-0.72.0, which remain unshipped drafts.', NULL, 'ref-01M0V6SS5G6P2M7AHBFA9G449Q', NULL, NULL, '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GPB9K6ASGKZZDHETD', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.74.0', 'Hardened Core', 'draft', '2027-01-15', NULL, 'Security invariant hardening, core parser test coverage, and repo hygiene enforcement. #31 close coverage gaps (md_parser, note_ingester, slack_users, MCP tools), #32 pre-embed secret redaction regression tests and chunk purge/re-index, #33 transcript suppression and clean repo hygiene.', NULL, 'ref-01M0V6SS5GV2PJ9E80HM8HR5G8', NULL, NULL, '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GG4HY5PE63HAEXYA0', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.75.0', 'Fleet Engine', 'draft', '2027-02-15', NULL, 'Unified fleet collection, streamlined scheduler topology, shared presentation layer, and multi-signal auto-promotion. #29 shared SQL read layer and web app mount, #23 pulse/fleet collector stack consolidation, #22 Mac Studio scheduler jobs reload, #4 Mac Studio pulse collector conflict recovery, #1 sustained-activity auto-promotion engine, #74 consolidate the dual end-of-day LLM vault synthesis jobs into one pipeline.', NULL, 'ref-01M0V6SS5GE1T1PHVMBG0J1021', NULL, NULL, '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0WSF76VM02W3MDN2A8MWJMA', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Sleuth Names Wired', 'active', NULL, NULL, 'Wire the live Slack user resolver (built in #114/#115/#116) into sleuth_candidates() so What''s Next stops showing raw Slack IDs for unmapped users.', 'sleuth_candidates() calls resolve_slack_user() per sender; a fresh unmapped Slack ID resolves via the live API (when configured) instead of falling back to the raw ID; existing tests plus a new regression test pass.', 'ref-01M0WSF76Y3TERRNTMGDYZQRVC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0WSF79NGW7P8N6EZZV1AS4H', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Embeddings Under Pressure', 'active', NULL, NULL, 'Investigate the 20+ hour, still-ongoing streak of obsidian-vault-embeddings failures — the GH-172 memory-pressure guard is correctly refusing to run (compressor holding 31-33GB against a 16GB ceiling), but sustained refusal with no escalation is an operational gap.', 'Root cause of the sustained memory pressure identified, and the job either resumes running successfully or the guard/alerting is adjusted so repeated refusals don''t go unnoticed for a full day.', 'ref-01M0WSF79QGYBYVW874DEZ75SD', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0WTRSPXJR6AT8K900CTE7PX', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Rename-Proof', 'shipped', NULL, '2026-08-25', 'Durable fix for the HiQS-Suite to HiQS-Labs org rename: self-deriving repo target, 307/308 redirect handling, and a permanent CI guard against reintroducing a stale org string.', 'health_issue_reporter.py derives its repo from git remote instead of a hardcoded literal; _request() follows 307/308 redirects; frontdoor-check.sh''s new RETIRED_OWNERS check runs in CI and is clean on development.', 'ref-01M0WTRSQ0DCQSWAM48EV72J9C', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M12XG4YM8J87CF5FP46QPF0Z', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.78.0', 'Sidecar', 'draft', NULL, NULL, 'Focus 5 horizontal layout mode and the CLIO prompt-log EINTR/silent-failure fix, split out of the #120 umbrella since neither fits an existing release theme.', NULL, 'ref-01M0V940AVPRE48N0S5H08EKTV', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M1DNJD7YT4A7KQMY2AWH2SER', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, NULL, 'draft', NULL, NULL, 'Ingest CLIO prompt logs into RebalanceOS semantic index', NULL, 'ref-01M1DNJD80BTGW1R2YTTJKMWXM', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M1J1SGH6WNVCAFW55KW49QWA', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Mirror-Proof', 'active', NULL, NULL, 'Digest stopped omitting repos: org-mirror dedupe (github_org_aliases + canonical repo identity in watched set, digest SQL, watchlist guard), stale-repos freshness signal in the digest, and commit-backfill root discovery that finds clones on a split install. API burn-rate root cause filed separately as #148.', 'Digest footer carries no mirror-doubled totals and names data-stale repos; runtime backfill coverage rows flip uncoverable->ok after the deliberate runtime pull.', 'ref-01M1J1SGH9R4PREDH7MKQ2NRDC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid) VALUES('mfi-01M0V940ASQHCQHZF33GVS34V8', 'rel-01M0V6SS5FEQMK5FVTZHR7KPRR', 'ref-01M0V940AVPRE48N0S5H08EKTV', 'cut', '2026-08-25T01:38:53Z', 'Focus 5 horizontal layout mode plus the CLIO silent-write fix; both surface-level items that fit the Green Board goal of one honest status surface.', NULL);
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid) VALUES('mfi-01M0Y92XY4HAZP6M83PSQSRV9G', 'rel-01M0V6SS5GG4HY5PE63HAEXYA0', 'ref-01M0Y92XY97J4MVPDQ52MTZEX0', 'dialed_in', '2026-08-26T05:36:01Z', 'Root cause: github-sync spends the token full 5000/hour allowance every hour and never completes, so every downstream signal in Fleet Engine is stale or absent. Nothing else in this build is trustworthy until the ingest path can finish a run.', NULL);
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid) VALUES('mfi-01M0Y92Y10QZA1R3PWXRCTQ663', 'rel-01M0V6SS5GG4HY5PE63HAEXYA0', 'ref-01M0Y92Y12J7GVD63E7HCA7276', 'dialed_in', '2026-08-26T05:36:01Z', 'The design for #54: two-tier cadence plus ETag conditional requests. Dialed in alongside #54 because fixing the budget without fixing the caller appetite only moves where the exhaustion happens.', NULL);
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid) VALUES('mfi-01M0Y92Y3STGYGS7DJA0QXRRD4', 'rel-01M0V6SS5GG4HY5PE63HAEXYA0', 'ref-01M0Y92Y3VXW3DDYAGZMRB7QJN', 'dialed_in', '2026-08-26T05:36:01Z', 'Second-order failure of #54 - the health reporter that would announce the outage is killed by the same 403, so the fleet goes quiet exactly when it has the most to report.', NULL);
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid) VALUES('mfi-01M0Y92Y6FRFNPYWRSKNSE225R', 'rel-01M0V6SS5GG4HY5PE63HAEXYA0', 'ref-01M0WSF76Y3TERRNTMGDYZQRVC', 'dialed_in', '2026-08-26T05:36:01Z', 'A resolver shipped in #114/PR #118 that nothing ever called; What Next has shown raw Slack IDs in production for days. Small fix, visible surface, and the same failure shape as the other dead controls this build is meant to end.', NULL);
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid) VALUES('mfi-01M12XGBNKP7DDN4SY7NWDE2A5', 'rel-01M12XG4YM8J87CF5FP46QPF0Z', 'ref-01M0V940AVPRE48N0S5H08EKTV', 'dialed_in', '2026-08-28T00:49:50Z', 'New home for the Focus 5 + CLIO umbrella, split out of Green Board.', NULL);
