INSERT INTO grandfather_entries(import_run, release_gid, rule, source_value, supplied_value, disposition) VALUES('imp-20260825T005821-050216', 'rel-01M0V6SS5GPFMAANZG4GYFAV4X', 'tracking-issue-missing', NULL, 'MIG-2BD48A', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7E5TVF5T9P8K77MNVK', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'CLIO multi-agent capture — ZCode, Codex, Agy alongside Claude Code', 'In progress', '2', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-139-CLIO-MULTI-AGENT-CAPTURE.md', NULL, '- **CLIO multi-agent capture — ZCode, Codex, Agy alongside Claude Code** ([#139](https://github.com/HiQS-Labs/rebalanceOS/issues/139)) — opened 2026-08-31, plan + capture-surface scouting done (ZCode exposes a `UserPromptSubmit` hook, so it is near drop-in; Codex and Agy have no prompt-submit surface and ride read-only tailers). Adds an `agent` field next to the existing device field; `clio:id` derivation deliberately unchanged. **Plan APPROVED by agy relay** (r1 changes requested — 1 Blocker + 2 Shoulds + 1 Nit, all applied, incl. correcting Agy''s store to JSONL transcripts and tailer JSONL-dedup; r2 5/5 confirmed). Phase 0 spike next. → [GH-139-CLIO-MULTI-AGENT-CAPTURE.md](PROJECT/2-WORKING/GH-139-CLIO-MULTI-AGENT-CAPTURE.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7ECJD3DV7AX4SQ3WWB', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 umbrella — horizontal layout mode + CLIO writer fix', 'In progress', '3', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-120-FOCUS5-UMBRELLA.md', NULL, '- **Focus 5 umbrella — horizontal layout mode + CLIO writer fix** ([#120](https://github.com/HiQS-Labs/rebalanceOS/issues/120)) — opened 2026-08-24, dialled into 0.70.0 Green Board. Adds a switch that lays each repo''s Focus 5 card out left to right while keeping the vertical stack as the default; and fixes the CLIO prompt-log writer, which reports success while seven prompts stay undelivered — `grep`/`cat` hit EINTR on the iCloud-managed target and a failed read is treated as an empty one. → [GH-120-FOCUS5-UMBRELLA.md](PROJECT/2-WORKING/GH-120-FOCUS5-UMBRELLA.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EMSRCM2ZZ06Y4X29M', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Refactor & Rename ''vault-sync'' to ''obsidian-vault-embeddings'' + Lightweight Embedding Engine', 'In progress', '4', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-81-OBSIDIAN-VAULT-EMBEDDINGS.md', NULL, '- **Refactor & Rename ''vault-sync'' to ''obsidian-vault-embeddings'' + Lightweight Embedding Engine** ([#81](https://github.com/HiQS-Suite/rebalanceOS/issues/81)) — Phase 0 spike completed; migrate Qwen3-Embedding-0.6B to BAAI/bge-small-en-v1.5 (384-dim, +20MB RAM, 7.3ms latency) and rename launchd job and scripts to `obsidian-vault-embeddings`. → [GH-81-OBSIDIAN-VAULT-EMBEDDINGS.md](PROJECT/2-WORKING/GH-81-OBSIDIAN-VAULT-EMBEDDINGS.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7ENJFA1ENS74YT8TT6', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Subsystem consolidation — too many subsystems reinventing the same concept', 'In progress', '5', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-5-SUBSYSTEM-CONSOLIDATION.md', NULL, '- **Subsystem consolidation — too many subsystems reinventing the same concept** ([#5](https://github.com/HiQS-Suite/rebalanceOS/issues/5)) — split into three sequenced PRs 2026-08-16 after post-ship QA. **PR1 open as [#6](https://github.com/HiQS-Suite/rebalanceOS/pull/6)**: severity mapping at the doctor boundary (closes #3), timestamp/label disambiguation (closes #2), and a one-way doctor→3-Eyes supervision bridge (addresses #4), plus three phases labelled honestly as incidental maintenance. QA by agy + Codex through the `/ponytail` and `/debug-mantra` lenses **reverted Phase 5a** (promoted a chunker with no caller — unanimous) and narrowed the branch''s claims: PR1 reduces *competing definitions*, not code volume. → [GH-5-SUBSYSTEM-CONSOLIDATION.md](PROJECT/3-COMPLETED/GH-5-SUBSYSTEM-CONSOLIDATION.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7E8EJP7WVK0MKE8FF9', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '5', 'GH-5 PR2 — one status vocabulary across every user-facing surface', 'In progress', '6', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-5-PR2-STATUS-VOCABULARY.md', NULL, '- **GH-5 PR2 — one status vocabulary across every user-facing surface** ([#5](https://github.com/HiQS-Suite/rebalanceOS/issues/5)) — drafted 2026-08-16, not started. Three words name the same top severity tier and all three are user-visible: `danger` (web badges), `fail` (`Check.status`), `error` (`Check.severity`). Deletion-forward by operator decision — visible dashboard changes accepted, net lines must go down; the highest-value deletion is collapsing `Check.status` and `Check.severity` into one field. Carries a verified correction: `_SOURCE_BADGE`/`_KIND_BADGE` are *categorical*, not severity, and are out of scope despite three prior sources claiming otherwise. → [GH-5-PR2-STATUS-VOCABULARY.md](PROJECT/3-COMPLETED/GH-5-PR2-STATUS-VOCABULARY.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EBY1MDMW6YSH688DA', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Build 0.74.0 Hardened Core', 'Queue / parked intake', '2', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/BUILD-0.74.0-HARDENED-CORE/SCOPE.md', NULL, '- **Build 0.74.0 Hardened Core** ([#31](https://github.com/HiQS-Suite/rebalanceOS/issues/31)) — 3-phase marathon plan covering test coverage gaps (#31), pre-embed secret redaction and purge (#32), and transcript suppression / hygiene (#33). → [BUILD-0.74.0-HARDENED-CORE/SCOPE.md](PROJECT/2-WORKING/BUILD-0.74.0-HARDENED-CORE/SCOPE.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EQ6Z65FB12192XPF3', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Build 0.75.0 Fleet Engine', 'Queue / parked intake', '3', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/BUILD-0.75.0-FLEET-ENGINE/SCOPE.md', NULL, '- **Build 0.75.0 Fleet Engine** ([#29](https://github.com/HiQS-Suite/rebalanceOS/issues/29)) — 5-phase marathon plan covering shared SQL read layer (#29), pulse collector stack consolidation (#23), scheduler jobs reload (#22), Mac Studio conflict recovery (#4), and sustained-activity auto-promotion (#1). → [BUILD-0.75.0-FLEET-ENGINE/SCOPE.md](PROJECT/2-WORKING/BUILD-0.75.0-FLEET-ENGINE/SCOPE.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7E74R1QQMR79TVGN0H', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Sustained-activity auto-promotion', 'Queue / parked intake', '4', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-1-SUSTAINED-ACTIVITY-AUTO-PROMOTE.md', NULL, '- **Sustained-activity auto-promotion** ([#1](https://github.com/HiQS-Suite/rebalanceOS/issues/1)) — captured 2026-08-16, moved here from the retiring `Hypercart-Dev-Tools/rebalance-OS#306`. Replace the commit-only 3-commit auto-promote threshold with a multi-signal tally (commits+PRs+issues+comments+reviews) at 5 actions, gated by a two-observation ≥20h wall-clock burst guard (revised after a Codex/agy consult found the original day-count guard was a no-op). Pending re-triage (`ratings_provisional: true`). → [GH-1-SUSTAINED-ACTIVITY-AUTO-PROMOTE.md](PROJECT/1-INBOX/GH-1-SUSTAINED-ACTIVITY-AUTO-PROMOTE.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7ESV9CAMS1HVR9F4T8', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, '`three_eyes pause` does not stop launchd firing the job', 'Queue / parked intake', '5', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/3EYES-PAUSE-DOES-NOT-STOP-LAUNCHD.md', NULL, '- **`three_eyes pause` does not stop launchd firing the job** ([#272](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/272)) — found 2026-08-14 while executing GH-250 R4. Ten jobs were paused and reported success; `pulse-web-sync` fired ~37 minutes later anyway, attached to the database and aborted a destructive 2.68M-row delete at batch 94 of 268. Only `launchctl bootout` genuinely quiesces a job, which means any pause used for triage or quarantine may be doing nothing. Carries a second defect: `fence-writers.sh` verify greps `three_eyes why` for a string paused jobs never print, and the string it *should* grep persists after resume — so pause state may not be readably at all today. → [3EYES-PAUSE-DOES-NOT-STOP-LAUNCHD.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/3EYES-PAUSE-DOES-NOT-STOP-LAUNCHD.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EYTW015TTJCB0PA3S', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'launchd fleet: keep/merge/retire decision for all 14 jobs', 'Queue / parked intake', '6', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-266-ARCHITECTURAL-AUDIT.md', NULL, '- **launchd fleet: keep/merge/retire decision for all 14 jobs** — parked 2026-08-14 from the GH-266 0.71.0 "Daily Driver" exit criteria. The GH-266 audit ([#266](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/266)) named the 10+ job fleet and its `three-eyes` supervisor as a source of over-engineering, and 14 `com.rebalance-os.*` jobs are installed today. Deliberately **not** a dogfooding gate: an agy review of the release blocks called it correctly as a design exercise bolted onto a stability run — a fleet decision is worth making, but it does not measure whether the minimized system holds up. Sequence it after 0.71.0''s window reports, so the decision is informed by observed behaviour rather than taken on the same clock. → [GH-266-ARCHITECTURAL-AUDIT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-266-ARCHITECTURAL-AUDIT.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EYJNJXJ0S0KFDXVWD', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, '/10days marathon-2026-07-25', 'Queue / parked intake', '7', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-PLAN-2026-07-25.md', NULL, '- **/10days marathon-2026-07-25** — 10-day GitHub issue sweep (2026-07-25): 35 issues updated in-window, 8 already fixed by prior marathons (verified via commit/PR evidence, not closed on GitHub — bookkeeping gap), 2 EPICs and 5 auto-filed device-health alerts out of scope, 2 held back to keep this marathon scoped (#144 overlaps #171''s file; #178 bundles 10 quarantined test failures with uncertain individual root causes). 10 survivors queued below (#139, #160, #166, #167, #170, #171, #186, #189, #201, #202); 3 of them (#167, #171, #189) reuse write-set analysis from the pre-existing, never-fired `MARATHON-2026-07-21` briefs. → [MARATHON-PLAN-2026-07-25.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-PLAN-2026-07-25.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
