INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EQW7N7D0J16QN685Y', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'CLIO projection: no malformed-source-row test', 'Queue / parked intake', '17', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-202-CLIO-MALFORMED-ROW-TEST.md', NULL, '- **CLIO projection: no malformed-source-row test** ([#202](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/202)) — queued 2026-07-25 via /10days, residual acceptance gap from GH-156. → [GH-202-CLIO-MALFORMED-ROW-TEST.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-202-CLIO-MALFORMED-ROW-TEST.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EGW66FKVM1X68D76S', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Simplify intake, definition, and exclusion of repos', 'Queue / parked intake', '18', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-NEXT-SIMPLIFY-REPO-INTAKE.md', NULL, '- **Simplify intake, definition, and exclusion of repos** (no issue yet — `gh_issue: NEXT`) — captured 2026-07-22, **Proposed, not started.** Watched-repo membership is currently decided by four separate sources (`project`, `activity`, `pushed`, `external`) plus an exclusion list (`github_ignored_repos`) that lives somewhere else entirely, in `temp/rbos.config`. The operator cannot answer "what is being monitored, and why" without reading all five. Proposal: collapse it to one explicit file-based flow in a single folder — **Auto-discovered → Confirmed Monitor List ↔ Exclude List** — where scanning populates the auto list and the operator promotes or excludes by moving entries. 3 phases; open questions still pending operator decisions. Assign a real issue number before promoting out of `1-INBOX`. → [GH-NEXT-SIMPLIFY-REPO-INTAKE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-NEXT-SIMPLIFY-REPO-INTAKE.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7ET5HEPZQYV8XMQ7CJ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Local Qwen embedding proof on this Mac', 'Queue / parked intake', '19', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-198-LOCAL-QWEN-EMBEDDING-PROOF.md', NULL, '- **Local Qwen embedding proof on this Mac** ([#198](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/198)) — **Phase 0 PASSED 2026-07-22; issue reopened to carry Phases 1–2.** The shared MLX Qwen runtime projected, embedded, and cold-queried a 1,560-document RebalanceOS `code` corpus against a gitignored staging DB in 222.1s at 1.468 GiB peak tree RSS, every vector stamped `Qwen/Qwen3-Embedding-0.6B|1024`, with a one-row stale-model repair verified; production `rebalance.db` stayed at 0 documents / 0 vectors and was never a write target. The only environment constraint found was that headless sandboxes cannot reach Metal — **no local-embedding blocker**. The currently populated ask-self index is a separate Gemini-backed system and is not a control. The Phase 0 branch (`codex/gh-198-local-qwen-embedding-spike`, `29dbd93`) was deliberately **not merged** — no code changed, evidence lives on the issue and in the doc — and was torn down. **Phase 1 next:** a reproducible stage-owned smoke test plus runtime metrics through the orchestrator/`doctor` path; Phase 2 (rollout decision, and whether ask-self stays Gemini-backed) is gated behind it. Spun out along the way: [#201](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/201), an explicit `--database` at a nonexistent path silently resolving to the canonical DB. → [GH-198-LOCAL-QWEN-EMBEDDING-PROOF.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-198-LOCAL-QWEN-EMBEDDING-PROOF.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EQ5WQF82DRC7ED7JT', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, '3-Eyes — unified local job supervisor', 'Queue / parked intake', '20', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-195-UNIFIED-SENTINEL.md', NULL, '- **3-Eyes — unified local job supervisor** ([#195](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/195)) — **MERGED 2026-07-22 via PR #196 (`fa7920c`); ACTIVE on the Mac Studio.** Optional, Python-first local job supervisor unifying the three sentinels we already run (XYZ debug flywheel · Cactus-Needle PDDA · Rebalance collector-health) under one TOML registry, one set of circuit breakers + relief valves, one generated dashboard, and one health/catalog surface. **Inert by default** — with no gitignored `config/runtime.env` (or `THREE_EYES_ENABLE!=1`) it is a clean no-op, so a downstream clone inherits nothing; kill-switches are `THREE_EYES_ENABLE=0` or a PANIC file in `~/.cache/rebalance-os/3-eyes/`. The registry (`utils/3-eyes/registry/*.toml`) is the source of truth — launchd/cron entries render from it and `DASHBOARD.md` is a CI-checked projection. **Managed today: `skill-sync`** (`com.rebalance-os.3eyes.skill-sync`, entering via the gitignored machine-local overlay) alongside the `selfcheck` demo job; the committed `collector-health` job is registered-but-not-installed, and the rest of the catalogued fleet is **observed, not managed**. Two irreversible edges stay human: adding to `commands.allow`, and any `gh`/`git push` route. Downstream surfaces: the `pdda-inbox` route drafts `PROJECT/1-INBOX/` captures with `ratings_provisional: true` (human promotes), `gh-issue` files to this repo, and `/focus-5.json` gains a fleet-health tile while active. **KeepAlive-server health refined 2026-07-22 (0.67.0)** — fleet health read only `launchctl list`''s status column, so the live pulse-server reported `FAIL(exit -15)` from a prior restart''s SIGTERM (the GH-146 misread, reproduced here); liveness now comes from the PID column. Two adjacent honesty defects fixed alongside: an unreachable `launchctl` (sandboxed shell, exit 1 + no output) silently read as "everything not-loaded" and now reports `unknown`, and the Focus 5 tile — which keyed on `failing == 0` — rendered that unreadable state as *"all jobs OK"* and now says UNKNOWN. New `supersedes` adoption guard makes `install` fail closed while a superseded incumbent is still loaded, so `collector-health` cannot become a second issue-emitter beside `health-check*` (the #139 defect). **P5 built 2026-07-24:** Gemma''s editable safety/classification instructions now live beside the runtime package and are sent as Ollama''s `system` message; the model selection is local runtime configuration, and the system fails closed if its instructions are missing. **Ongoing: adopt the remaining automations** (skill-sync done; git-pulse, Cactus-Needle/Sleuth, XYZ-debug sentinel next). Entry points: `utils/3-eyes/` · `/3-eyes` · companion `/launchd-triage`. → [GH-195-UNIFIED-SENTINEL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-195-UNIFIED-SENTINEL.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EN9TY1BDMV51B60MR', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, '[CRITICAL] HiQS loses direct GitHub commits and file-level change signals', 'Queue / parked intake', '21', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-155-CRITICAL-DIRECT-COMMIT-SIGNALS.md', NULL, '- **[CRITICAL] HiQS loses direct GitHub commits and file-level change signals** ([#155](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/155)) — captured 2026-07-18, **issue CLOSED 2026-07-19**. First link in the #155→#157→#169 "one more thing" chain: the measured loss of direct-to-branch and merge commits from the HiQS signal path. Its remaining scope was absorbed by **[#169](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/169)**, whose Phase 3 exists specifically to end that chain by making commit-coverage continuously derivable instead of rediscovered. Capture doc still sits in `1-INBOX` at `status: triage` and is a candidate for archiving to `4-MISC` once GH-169 Phase 1 lands. → [GH-155-CRITICAL-DIRECT-COMMIT-SIGNALS.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-155-CRITICAL-DIRECT-COMMIT-SIGNALS.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7EE8M9W327DGJF164Q', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Skill: rebalance live-signal-active-git (morning brief)', 'Queue / parked intake', '22', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-190-LIVE-SIGNAL-ACTIVE-GIT-SKILL.md', NULL, '- **Skill: rebalance live-signal-active-git (morning brief)** ([#190](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/190)) — **SHIPPED 2026-07-22** (merged via PR #191, CI green). Invokable `/rebalance` skill at `.claude/skills/rebalance/` that fuses the cached HiQS "what''s next" verdict with a deterministic, read-only device-wide git-activity scan (worktrees are one facet, not the whole) and classifies each branch ACTIVE/WARM/STALE/MERGED/SYNCED vs trunk. agy `/relay-xyz` QA closed Approved (added SYNCED tag; fixed zero-commit-repo edge). Globally symlinked; dir flattened from the initial nested layout so it registers as `/rebalance`. → [GH-190-LIVE-SIGNAL-ACTIVE-GIT-SKILL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-190-LIVE-SIGNAL-ACTIVE-GIT-SKILL.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7E6N3ZQG2HPCDKT1M3', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Float: Dock reopen + panel resize', 'Queue / parked intake', '23', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-187-FOCUS5-PANEL-FIXES.md', NULL, '- **Focus 5 Float: Dock reopen + panel resize** ([#187](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/187)) — **SHIPPED 2026-07-21**. Dock reopen restores the ordered-out panel. Native horizontal/vertical resizing works with an unbounded height and the intentional 420pt width cap; the visible top gap was the hidden-titlebar hosting safe area plus top gutter, now removed and guarded by a real-panel regression test. 53 Swift tests pass; packaged app verified live. → [GH-187-FOCUS5-PANEL-FIXES.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-187-FOCUS5-PANEL-FIXES.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7E043BF3B82NM0RSYR', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Ingest Claude Code Cloud jobs (web sessions) + status', 'Queue / parked intake', '24', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-128-CC-CLOUD-JOBS-INGEST.md', NULL, '- **Ingest Claude Code Cloud jobs (web sessions) + status** ([#128](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/128)) — captured 2026-07-14. **Phase 0 done:** discovered the surface behind the VS Code "Web" sessions tab — `GET api.anthropic.com/v1/code/sessions` (subscription OAuth bearer, no beta header, no API key); proved Managed Agents (`/v1/deployment_runs`) is API-key-only (`401`) and triggers ride the `RemoteTrigger` tool. **Phase 1 done (wired DORMANT):** new `claude_cloud` derived-scan collector registered into the GH-125 `candidates=` seam, enriched with per-branch PR merge status (open→"Review PR #N", failed→"FAILED", merged→done); ships gated behind `claude_cloud_signal_enabled` (default off) so it contributes zero to the live verdict until promoted. Observation surface = a data-quality grade block (`utils/claude_cloud_daily_grade.py`) upserted into `0. Today''s Notes.md` (live-verified: 4 sessions on 2026-07-14, grade A). 8 tests. **Phase 2 (promote to first-class: raw table + bundle field, flip the flag) is gated on a kill-check after watching the grade.** → [GH-128-CC-CLOUD-JOBS-INGEST.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-128-CC-CLOUD-JOBS-INGEST.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7E69GYRAJFJNCRVJA3', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Pulse dashboard redesign — master (one module per day)', 'Queue / parked intake', '25', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-136-DASHBOARD-REDESIGN.md', NULL, '- **Pulse dashboard redesign — master (one module per day)** ([#136](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/136)) — opened 2026-07-18. Umbrella for the module-a-day redesign against Claude Design briefs; holds the 10 standing invariants each day inherits (one timestamp helper, one shared row, narrow containers stack, verify by rendering, …) plus the module ledger and the dashboard-scoped verification gate. **Day 0** = the consistency refactor (#135, merged via PR #143 2026-07-18); **Day 1** = Calendar day-grid ([#137](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/137), shipped `09be427`). Remaining modules not started. → [GH-136-DASHBOARD-REDESIGN.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-136-DASHBOARD-REDESIGN.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F2TVVYFZJK81VZMAT', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Web app theme color picker', 'Queue / parked intake', '26', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-154-THEME-COLOR-PICKER.md', NULL, '- **Web app theme color picker** ([#154](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/154)) — captured 2026-07-18. **Day 2 of [#136](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/136)**, and the first cross-cutting one: Settings → Color theme with 4 presets + Custom, 7 tunable colors, live preview (Claude Design, `PROJECT/1-INBOX/dashboard-redesign-2026-07-18/`). The picker is small; the enabling work is collapsing **~190 hardcoded color literals across 3 Python-embedded stylesheets** onto a ~10-token vocabulary (7 settable + 3 derived), since all CSS in this repo is Python-embedded and only one 12-property `:root` exists (`web_components.py:19`). Two decisions shape it: `render_shell()` is a single chokepoint covering all 4 live routes, but `/` is a **static build artifact**, so theming is client-side (pre-paint inline script + `localStorage`) rather than a server re-render; and derivation lives in JS only, with Python shipping pre-derived defaults plus a Playwright drift test. 7 phases, P6 (durable `config.py` persistence) deliberately splittable. **SHIPPED 2026-07-19 via [PR #163](https://github.com/Hypercart-Dev-Tools/rebalance-OS/pull/163)** — token vocabulary + full `:root`, all three Python-embedded stylesheets tokenized, and Settings → Color theme, merged to `development` (`feat/theme-picker`, tip `613f77b`); the `/settings` route and preset grid are live there. *(This line read "Planning — no code written" until 2026-07-22; a first correction that day then over-corrected to "built but unmerged" by trusting the doc''s own stale `status:` field instead of checking `development` — both wrong, both fixed here against PR state.)* Three **post-merge** items remain: legacy-alias retirement, a true first-paint (CDP) check, and the operator visual pass on the light theme. → [GH-154-THEME-COLOR-PICKER.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-154-THEME-COLOR-PICKER.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FFDJ1YRP2RRWDSKNS', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Pulse dashboard consistency refactor', 'Queue / parked intake', '27', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-17.md', NULL, '- **Pulse dashboard consistency refactor** ([#135](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/135)) — captured 2026-07-17. **Day 0 of [#136](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/136).** Reference design complete (Claude Design, `PROJECT/1-INBOX/dashboard-redesign-2026-07-17/`); four-phase contract written: `format_timestamp()` extending the existing GH-130 `tz_utils`, one shared row component with zebra striping, seven per-module fixes, one header-casing system. Presentation only. Ran as the single lane of [MARATHON-2026-07-17](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-17.md); all 4 phases built, reviewed, and committed 2026-07-18 (1415 passed / 15 pre-existing failures, page regenerates, doctor + pdda clean). **DONE — merged 2026-07-18 via PR #143** (corrected 2026-07-21; previously misread as unmerged). 2 residual out-of-scope acceptance gaps (health-banner bare relatives from `doctor.py`; org prefixes in repo-pie labels) tracked as [#189](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/189); screenshots were never taken (untracked, not reopened). → [GH-135-PULSE-DASHBOARD-CONSISTENCY.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-135-PULSE-DASHBOARD-CONSISTENCY.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FMNR5BWQHC29D3DAN', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Collector health signal reports a working system as broken', 'Queue / parked intake', '28', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/SIGNAL-HEALTH-NUANCE.md', NULL, '- **Collector health signal reports a working system as broken** ([#146](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/146)) — captured 2026-07-18. Months of "collectors are unstable" traced to the **health signal**, not the collectors: 7 of 8 non-ok checks on 2026-07-18 were misreads. `scripts/daily_sync.sh` exits 1 if *any* sub-source errors, so a transient GitHub rate limit fails a 49-minute run that otherwise succeeded (7 of last 10 runs ended `finished with errors`); `doctor` reports a stale `launchctl` exit status as current health; device-scoped pulse-collector checks warn on the Mac Studio about laptops that are not always on. **4th root cause found 2026-07-18:** `doctor.py:1015` computes the deep-work check''s "today" in UTC, so after 17:00 PDT all five tracked projects report `quiet <tomorrow>` — same bug class as GH-129''s day-boundary tz pin, fixed there and missed here. 4 fixes scoped: exit semantics, JSON-based launchd check, device scoping, local day boundary. **SHIPPED 2026-07-18 via PR #151** (4-phase marathon, all approved): measured **6 warns → 5** against a target of 0 — P3 (device scoping) and P4 (local day boundary) delivered; P2 left `launchd:pulse-server -15` (SIGTERM) unfixed despite its brief naming it, and `launchd:daily-sync` is honest now ("stale/unknown") but still WARNs. Full suite zero regressions vs base; one regression *was* introduced and caught pre-merge (P2 changed a launchd message without updating `test_scheduler_liveness.py`, which the scoped gate deselected). P1''s effect is not observable until the 06:30 PT sync. `email data` turned out **not** to be a real defect — #147 correctly refixed it by keying freshness on `synced_at` rather than `received_at`. **3 gaps remain** (pulse-server -15, daily-sync WARN-vs-INFO, hardcoded device ids) — note `doctor.py`''s launchd-exit-status handling was touched again by the [signal-health-nuance](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/SIGNAL-HEALTH-NUANCE.md) marathon (PR #158, 2026-07-19); the pulse-server -15 gap may now be closed, not independently re-verified here. → [GH-146-HEALTH-SIGNAL-ACCURACY.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-146-HEALTH-SIGNAL-ACCURACY.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F07XECTDTTBNWKF4G', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '144', 'GH-144 one-shot sentinel prompt', 'Queue / parked intake', '29', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-144-SENTINEL-PROMPT.md', NULL, '- **GH-144 one-shot sentinel prompt** ([#144](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/144)) — drafted 2026-07-18. A **run-once** Antigravity task (not the general sentinel) that reads the 2026-07-19 06:30 PT `daily-sync` log, classifies the 403 as secondary (burst, confirms #144 hypothesis 2) vs primary (quota, kills it) from `5fc670d`''s `retry-after` logging, and posts one comment to #144. Files nothing, opens no PRs, so it cannot collide with the live `health_issue_reporter`. **Schedule 07:45 PT or later** — the run takes ~49 min. Encodes the trap GH-146 created: `launchd:daily-sync` is no longer a valid signal for this test, since P1 made a rate-limit error exit 0. → [GH-144-SENTINEL-PROMPT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-144-SENTINEL-PROMPT.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F9X4JVP7Y3SWVBJ0W', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Collector sentinel — scheduled detect → triage → repair → PR loop', 'Queue / parked intake', '30', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/AGY-SENTINEL.md', NULL, '- **Collector sentinel — scheduled detect → triage → repair → PR loop** — drafted 2026-07-18, straight to 2-WORKING; no GH issue yet. A recurring Antigravity task that runs `rebalance doctor`, classifies each finding (real / working-as-configured / transient / environmental) against a trap list seeded from real misclassifications, files + captures + parks genuine defects on the PDDA rails, repairs one at a time on a `sentinel/*` branch off `development`, and **stops at a PR** — `main` is protected and Principle 7 puts execution with the operator. Gate baseline is now `241 passed, 10 skipped` (was 178 before #147 and GH-146 added tests — a stale baseline silently disables the assertion, so re-derive it); §4a adds a count-must-exceed-baseline assertion because a gate over existing tests cannot prove a new one exists — and GH-146 P2 proved the sharper corollary, that a new test existing cannot prove it tests what you asked for. **Phase 0 is blocking:** `scripts/health_issue_reporter.py` is already filing health issues on two loaded launchd jobs (`health-check`, `health-check-triage`), so standing the sentinel up as a second emitter reproduces the twin-issue defect that #139 was closed by deleting. Not scheduled. → [AGY-SENTINEL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/AGY-SENTINEL.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FGM0YG8JNAAWVGHHS', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'ROADMAP→dashboard collector', 'Queue / parked intake', '31', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/PDDA-INTEGRATION/ROADMAP-SIGNAL-SCAN.md', NULL, '- **ROADMAP→dashboard collector** — 1-INBOX draft, not yet promoted. A new `roadmap` source scanning PDDA `ROADMAP.md` ledgers into the dashboard. Sequenced **behind** the now-promoted signal-quality contract so it is born observable (inherits the health fields) instead of shipping ungraded. Draft pending 5 operator decisions (§6) and partial cross-device registry rollout (1 of 3 devices). **Also captured (2026-06-30), unscoped:** a speculative Phase 5 — once the collector ships, its cross-repo `roadmap_signals` table is a second potential consumer beside the dashboard plane, seeding XYZ/tick task lanes *across repos*. Not designed; revisit after Phase 2. → [ROADMAP-SIGNAL-SCAN.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/PDDA-INTEGRATION/ROADMAP-SIGNAL-SCAN.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FTV343JR9V9MTRW2B', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'CLIO — durable, idempotent writes to the shared Obsidian note', 'Queue / parked intake', '32', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-19-CLIO-DURABLE/MARATHON.md', NULL, '- **CLIO — durable, idempotent writes to the shared Obsidian note** — drafted 2026-07-19, on `work/clio-durable-obsidian-writes`. Closes CLIO''s known best-effort merge gap: the exporter''s per-device line-count **cursor** is load-bearing for correctness (it advances whether or not the write survives sync), with no content-level idempotency or conflict-copy reconciliation — so a lost sync round-trip, corrupt cursor, or Obsidian/iCloud conflict copy can silently drop or duplicate prompts. Plan: **content-addressed entry IDs** (invisible `<!-- clio:id:HASH -->`) that demote the cursor to a mere optimization + make re-emit idempotent, **conflict-copy reconciliation** (absorb orphaned siblings, quarantine not delete), and verify-after-write. Coupled Swift change: `PromptLogReader` must skip HTML-comment lines. Phase 3 (per-device regions, mirrors Git Pulse namespacing) deferred. **Also shipped same day:** default launchd cadence 5 min → **1 min** (docs + live job on Mac Studio) — which raises collision odds and motivates this work. **SHIPPED 2026-07-19** via [MARATHON-2026-07-19-CLIO-DURABLE](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-19-CLIO-DURABLE/MARATHON.md) — both phases approved (agy), `swift build` gates green, 48 Swift tests pass. Phase 0 (spike) was deliberately dropped as operator/environment work, not headless-automatable. One bash-3.2 runtime defect (empty-array abort under `set -u`) escaped the `swift build` gate and reached a live machine before being caught in post-run verification (`d96439b`) — the gate never executed a line of the bash exporter, which is why GH-156 P1 gives it a real test surface. **Archived to `3-COMPLETED` 2026-07-19**; operator litmus (install on both machines, watch a real conflict reconcile) still outstanding. → [CLIO-DURABLE-IDEMPOTENT-WRITES.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/CLIO-DURABLE-IDEMPOTENT-WRITES.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F1JQE0F656TK3FR3Q', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'CLIO prompt projection silently loses historical entries', 'Queue / parked intake', '33', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-156-CRITICAL-CLIO-PROJECTION-RECONCILIATION.md', NULL, '- **CLIO prompt projection silently loses historical entries** ([#156](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/156)) — captured 2026-07-18, **rescoped 2026-07-19**. P0 historical-integrity defect: the rendered Obsidian note, not the raw JSONL, is the operator-facing record, and the line-count cursor claims delivery whether or not the write survived. Original capture predated the durable-writes marathon by one day, so its Phase 1 (stable IDs) and most of Phase 2 (idempotent reconciliation, quarantine, dry-run preview) **already shipped** — the doc is rescoped to the genuine remainder: a **source-owned manifest** of rendered IDs (zero `manifest` refs in `INSTALL.md` today), **cross-run loss detection** (the shipped verify-after-write is intra-run only — it cannot notice an entry delivered last week and since deleted), and **targeted repair** (the only lever today is deleting the state file, i.e. a full replay). Reproduced live during the 2026-07-19 Mac Studio reinstall, which added the load-bearing finding the capture missed: **~330 legacy entries carry no `clio:id`** and are invisible to dedup, so repair-before-backfill would duplicate all of them — demonstrated in miniature when a rewound cursor produced 3 duplicate blocks (detected by multiset diff, reverted). Marker displacement is real and already present (marker at line 331 of 4291). 3 phases on `marathon/gh-156-critical-clio-projection-reconciliation-2026-07-19`. P1 also extracts the exporter out of the `INSTALL.md` heredoc into a tested script (`utils/CLIO/prompt-log-to-md.sh` + `test/clio-exporter.sh`) — it had no test surface at all before. **DONE — fired and merged 2026-07-20 via PR #176**, all 3 phases approved (corrected 2026-07-21; this line previously said "Not fired", stale). One acceptance gap remains (no malformed-source-row test) and `--repair` has never been run against the live `0. Claude Prompts.md` note (operator-supervised step, not yet done). → [GH-156-CRITICAL-CLIO-PROJECTION-RECONCILIATION.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-156-CRITICAL-CLIO-PROJECTION-RECONCILIATION.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FBGX0R5DFH9033654', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'rebalance-embed reaches 46.9 GB phys_footprint — MLX Metal buffer cache never released', 'Queue / parked intake', '34', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-215-MLX-EMBED-CACHE-LEAK.md', NULL, '- **rebalance-embed reaches 46.9 GB phys_footprint — MLX Metal buffer cache never released** ([#215](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/215)) — captured 2026-07-27. **Root cause behind the 07-25 / 07-26 / 07-27 machine events**, found by reading source after the third recurrence. The embedding backend is **MLX, not torch** (`embedder.py:65-74`), and MLX allocates **Metal** buffers charged to `phys_footprint` as `iokit` and **never counted in RSS** — which alone explains the 46.9 GB-vs-73 MB signature that made three investigations inconclusive. MLX caches freed buffers with an effectively unbounded default limit, and the repo does **no** MLX cache management: `mx.clear_cache` / `set_cache_limit` / `set_memory_limit` all exist in the installed MLX 0.31.2 and appear **zero times** across `src/` and `utils/`. The batch loop (`embedder.py:172-186`) embeds 32 chunks per iteration with no release between them; the model itself is cached correctly, so this is per-batch accumulation, not reloading. This **reframes [#213](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/213)** from "the fix" to "the backstop" — that issue repairs the guard that failed to notice, this one repairs the allocation. Evidence (PROVEN, quoted): PID 1391 at 46,932.2 MB footprint / 73.2 MB RSS; free RAM 0.09 GB with compressor 28.99 GB and swap 24.7/26 GB at 07:44:40; `job_guard` ran 233 jobs that day and tripped **zero** times. Confidence high but **INFERRED** — `mx.get_cache_memory()` has never been sampled live (no Metal device from a sandboxed shell), which is exactly what #216 exists to settle. Not started. → [GH-215-MLX-EMBED-CACHE-LEAK.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-215-MLX-EMBED-CACHE-LEAK.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F453TPN3FTCP1N8XC', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Instrument MLX memory per batch — the dominant consumer is unobserved', 'Queue / parked intake', '35', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-216-MLX-MEMORY-INSTRUMENTATION.md', NULL, '- **Instrument MLX memory per batch — the dominant consumer is unobserved** ([#216](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/216)) — captured 2026-07-27. The largest memory consumer on this machine is invisible to every instrument we own; three events were each investigated after the fact from external samplers, and the responsible allocation was identified only on the third attempt, by reading source rather than telemetry. **Three blind spots stack:** RSS instruments cannot see Metal at all (`job_guard` logged `peak_rss_gb: 0.232` for a process measured at 46.9 GB); the guard''s window is *shorter than the leak''s*, since `guarded_embedding` (`_job_guard.py:167-180`) decorates embedding **leaf** functions so each call builds a fresh `MemoryCeiling` with `peak_rss = 0` — PID 1391 wrote three records (10.7 s / 1.5 s / 35.6 s) across a 35-minute lifetime, so cumulative growth cannot appear there by construction; and the external sampler is 60 s / per-process, able to say a Python process grew but never which allocation. Plan: log `mx.get_active_memory()` / `get_cache_memory()` / `get_peak_memory()` every N batches. **Decisive either way** — a monotonic cache climb confirms #215, a flat cache with rising active memory refutes it and redirects the fix. Also closes a second audit gap: `sys-mem-watch.sh` records `free_gb` but **not** `inactive_gb` / `speculative_gb`, while the guard''s available-memory floor computes `free + inactive + speculative` (`job_guard.py:155-184`) — so whether that floor should have tripped at 07:44 is currently **unmeasurable**, neither exonerated nor convicted. That floor is the half of the guard that does *not* depend on per-process accounting, i.e. the half most likely still sound. Not started. → [GH-216-MLX-MEMORY-INSTRUMENTATION.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-216-MLX-MEMORY-INSTRUMENTATION.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F8E0NF52ZK3FY8JHJ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Hard MLX memory limit — fail the job, not the machine', 'Queue / parked intake', '36', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-217-MLX-HARD-MEMORY-LIMIT.md', NULL, '- **Hard MLX memory limit — fail the job, not the machine** ([#217](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/217)) — captured 2026-07-27. In all three events the **machine** absorbed the damage, never the job: free RAM 0.09 GB, compressor 28.99 GB, swap 24.7/26 GB, and the two 07-27 episodes self-recovered only because the process happened to exit — 07-25 and 07-26 did not. `mx.set_memory_limit()` closes that from **inside** the process, in the one component that knows how much Metal memory was requested. Deliberately redundant with #215: that fixes *why* memory grows, this bounds *how bad it gets* when the fix is wrong, incomplete, or later regressed — and the 07-27 data is a direct argument for it, since three consecutive incidents got through precisely because a single line of defence keyed on a single metric. Independent of the #215 hypothesis, since it constrains the outcome rather than the cause. Two constraints carried in the capture: size it as a **fraction of physical RAM** (matching `job_guard.py`''s `DEFAULT_MAX_RSS_FRACTION = 0.35`) rather than hardcoding 64 GB, and **release the `rebalance-embed` flock on the failure path** — `README.md:254` already documents an "already running" mode, and trading a memory blowup for a permanently stuck lock is a worse incident. Sequenced **after** #215 and ideally after #216 supplies real numbers; a guessed ceiling that fails legitimate passes is how safety mechanisms get switched off. Not started. → [GH-217-MLX-HARD-MEMORY-LIMIT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-217-MLX-HARD-MEMORY-LIMIT.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FG3W03Y3EDMVY10DC', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'doctor reads an empty launchctl list as "no jobs loaded"', 'Queue / parked intake', '37', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-219-REBALANCE-MEMORY.md', NULL, '- **doctor reads an empty launchctl list as "no jobs loaded"** ([#218](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/218)) — captured 2026-07-27. **Same bug class as [#146](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/146)** — a health signal reporting a working system as broken. `_launchctl_list()` (`doctor.py:502-510`) returns `None` only on `FileNotFoundError`/`SubprocessError` and **never inspects `returncode`**, so a `launchctl` that runs but yields nothing returns `""`; the caller''s guard reads `if launchctl_output is None` (`doctor.py:603-606`), `"" is not None`, and every policy job is reported missing — **14 false WARNs plus "install it with `bash scripts/install_*.sh`"** against jobs that are loaded and running. The intent is already correct in that comment; the check is just too narrow to deliver it. On macOS a working `launchctl list` always returns at least system labels, so an empty listing is evidence of failure, never of an empty fleet. **PROVEN** — reproduced both ways live on 2026-07-27 (`launchctl list | grep -c rebalance` = 14 while doctor warned all 14 missing). Found because it cost the #215 investigation a **false lead**: "no scheduler loaded, yet something fires embedding passes every 40-70 min" was a contradiction manufactured entirely by the instrument — the real answer being `vault-sync` hourly at :15 plus `daily-sync` 06:30 (~49 min), nothing unexplained. Sequenced **first** in [GH-219 Rebalance memory](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-219-REBALANCE-MEMORY.md) because that project uses `doctor` as a gate (and Lane 7''s standing detection lands as a `doctor` check). Not started. → [GH-218-DOCTOR-LAUNCHCTL-FALSE-NEGATIVE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-218-DOCTOR-LAUNCHCTL-FALSE-NEGATIVE.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F52SEHB53E63KJDS1', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Rebalance memory — unified project (8 lanes)', 'Queue / parked intake', '38', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-219-REBALANCE-MEMORY.md', NULL, '- **Rebalance memory — unified project (8 lanes)** ([#219](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/219)) — opened 2026-07-27, not fired. **Umbrella and single owner of Rebalance''s memory use on this device**; widened from a 5-lane MLX marathon on operator instruction so no memory surface is left un-owned and able to return as "one more thing" after completion. Lanes 5–7 add fleet inventory + declared budgets, a guard-coverage audit, and standing regression detection (one `doctor` check over already-collected sampler data — deliberately *not* the monitoring subsystem #213 argued against). Breadth is bought with measurement, which is cheap and exhaustive; depth stays bounded because **remediation is conditional on a numeric budget breach** — every Rebalance process is in scope for measurement, only violators for fixing. Numeric contract on this 64 GB machine: ≤8 GB per process, ≤16 GB aggregate concurrent, `free_gb` ≥4.0, compressor ≤8.0, swap ≤12.0, over a representative day of ≥12 embedding passes. **Codex `/relay-xyz` r1: 2 Blockers + 3 Shoulds, all accepted and applied** — the blockers being no PID→entry-point attribution (leaving 2 of 3 observed episodes unattributable *by construction*) and "peak footprint" alone being unable to establish whole-machine starvation is solved. Sequences Sequences [#218](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/218) → [#216](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/216) → [#215](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/215) → [#217](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/217) → [#213](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/213) as **instrument → measure → fix → bound → backstop**. The five are *not* independent, so issue-number order would be actively wrong: #215 is INFERRED until #216 measures it, #217 must be sized from #216''s numbers, #213''s ceiling only means the right thing once footprint semantics are settled, and #218 repairs the health instrument the marathon itself gates on. Lane A (#216→#215→#217) shares `embedder.py` and must run strictly sequentially; Lane B (`utils/job_guard.py`) and Lane C (`doctor.py`) are path-disjoint and may run concurrently — note `ingest/_job_guard.py` and `utils/job_guard.py` are different files despite the names. Carries three open questions, the sharpest being that **only 1 of 3 episodes on 07-27 is confirmed as `rebalance-embed`** (PIDs 16871 and 2886 match on binary, peak and RSS profile but have no `job_rss.jsonl` record at all) — if those are a second path to the same allocation, the #215 fix is incomplete. → [GH-219-REBALANCE-MEMORY.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-219-REBALANCE-MEMORY.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FNXXPQKAN4JBNTTG8', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Skill: rebalance — optional PDDA lifecycle signal (third axis)', 'Queue / parked intake', '39', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-193-REBALANCE-PDDA-LIFECYCLE-SIGNAL.md', NULL, '- **Skill: rebalance — optional PDDA lifecycle signal (third axis)** ([#193](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/193)) — captured 2026-07-22. Follow-on to #190: adds an **optional, non-load-bearing** third reconciliation axis to `/rebalance` — a repo''s own PDDA ledger (`PROJECT/2-WORKING/` basenames+mtimes, lifecycle counts, `pdda=yes|no`) as *declared intent*, alongside the HiQS signal and git activity. Two-layer split: collector emits structural facts only (no prose-parsing, **never runs `pdda.sh` or any repo script**); synthesis reads frontmatter/Status as advisory, allowed-stale. PDDA never feeds the git freshness tag; non-PDDA repos stay byte-identical. Plan went through a Codex `/relay-xyz` review (Changes requested → all findings accepted): `pdda_mtime` now OS-selects BSD vs GNU `stat`, and the marker tightened from the non-unique `ROUTER.md` to the PDDA-unique `PROJECT/PDDA.md`. → [GH-193-REBALANCE-PDDA-LIFECYCLE-SIGNAL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-193-REBALANCE-PDDA-LIFECYCLE-SIGNAL.md)', '2026-09-01T05:02:54Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F2QAEZ2Q2WHDHQ8YQ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Architectural Audit: Complexity, DRY, and System Stability', 'In progress', '7', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-266-ARCHITECTURAL-AUDIT.md', NULL, '- **Architectural Audit: Complexity, DRY, and System Stability** ([#266](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/266)) — opened 2026-08-11. Consolidate duplicate ingest logic and implement bulletproof governance rules to prevent system over-engineering. → [GH-266-ARCHITECTURAL-AUDIT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-266-ARCHITECTURAL-AUDIT.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FVC2YFM3AGYYZME7S', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'HiQS build — marathon decomposition', 'In progress', '8', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-HIQS-BUILD/MARATHON-PLAN.md', NULL, '- **HiQS build — marathon decomposition** — authored 2026-08-03; **M1 and M2 FIRED AND COMPLETE**, 10 of 18 phases approved. Five sequential marathon plans (18 phases) covering every module in the HiQS §11 tree, with four operator checkpoints between them. The honest split: **all ~1,885 LOC of the core is marathon-able; none of the phase-exit gates from Phase 1 onward are** — the eval answer keys must be authored from the operator''s own memory and resolved by grep (an agent authoring them invalidates Decision 8 by construction), OAuth consent is interactive, and the Phase 4 exit is a week of wall clock. Preflight caught two defects that would have failed mid-run: reviewer-equals-builder (exit 2 at phase 2 of all five) and bare `p1` phase ids colliding across plans on the permanently-spent `MARATHON-<ID>-TURN` token. **Next: operator checkpoint A — this is a human gate, not a phase.** Author `eval_queries.json` from memory per §6.3 (grep only to resolve, drop what you cannot locate, freeze it, record the SHA), score MiniLM vs Qwen3, and read the disagreement set query by query. **It can delete a dependency:** if fused retrieval does not beat FTS-only by >=10 points, torch leaves the plan and M4/M5 change shape — which is why M3 must not fire first. Five halts occurred across M1/M2 and four were plan defects, three of them the same class: a phase scoped below its own deliverable (pyproject.toml, test_contract.py, then plugins.py + vault.py). The fifth was the §5 design gap the consult resolved. Also learned: `--retry` does not skip earlier phases, so an approved phase left in a plan gets re-opened and burns its cap on settled work — hence the M2-CONT-* continuation plans. → [MARATHON-PLAN.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-HIQS-BUILD/MARATHON-PLAN.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FHP0W97ABHCY0582X', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'HiQS — clean-room rebuild of the signal pipeline', 'In progress', '9', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/HIQS-PROJECT.md', NULL, '- **HiQS — clean-room rebuild of the signal pipeline** — plan rev 5, promoted to 2-WORKING 2026-08-03; not yet issue-tracked (`gh_issue: TBA`). Ground-up rebuild: plugin-native sources → one local SQLite → hybrid FTS5 + vector search behind one seam → exactly one attested ranking read by MCP, CLI, and one web page. Target ≤3,000 LOC core, 4 top-level deps, observability from the first commit. Codebase lives **in this repo at `HiQS/`** (own `pyproject.toml`, clean room enforced by an import-boundary test rather than a repo boundary); the DB stays at the canonical app-data path, never in the tree. Fresh DB, no migration — the incumbent keeps running untouched. 7 phases (0 skeleton → 1 vault + hybrid search + the retrieval eval that closes the embedding-model decision → 2 GitHub → 3 calendar/ask/MCP → 4 surfaces + ops → 5 on-demand only → 6 extraction), each with a QA gate. **`HiQS/` is a staging home:** the code spins out to [HiQS-Suite/HiQS](https://github.com/HiQS-Suite/HiQS) (public, created 2026-08-03) once stable, and **this repo is archived within weeks** — so Phase 6 carries the extraction, the plan doc''s move, and a blocking disclosure gate (the frozen eval sets are built from the private vault and include client names, and were specced to be committed into what becomes a public repo). Reviewed end-to-end by an agy relay (2 rounds, 6 findings, all fixed; closed PARKED). **No code written.** **Next:** open the tracking issue **on HiQS-Suite/HiQS, not here** (an archived repo''s issues freeze), then Phase 0. → [HIQS-PROJECT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/HIQS-PROJECT.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F980A6H38YHCVWGF9', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Commit history coverage — backfill direct + merge commits', 'In progress', '10', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-169-COMMIT-HISTORY-COVERAGE.md', NULL, '- **Commit history coverage — backfill direct + merge commits** ([#169](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/169)) — captured 2026-07-19 off a read-only HiQS litmus test that could not answer "where does CLIO live and where did it come from". The answer existed all along in one unindexed commit (`cfeafe4`, *"bring CLIO into rebalance-OS as its canonical home"*), which names the origin repo, upstream SHA `ef96a44`, and destination `utils/CLIO/`. Measured gap: **182 of 938 commits (19.4%)** on `development` since 2026-05-01, spanning two classes both missed by *both* existing paths — direct-to-branch commits (mostly `docs:`/`chore:`, i.e. where design intent is written down) and **merge commits** (not PR commits, so `sync_github_repo()` never persists them). RCA found four compounding causes, all verified live: the Events API 300-event/90-day ceiling (`events: 300` — the exact ceiling), actor-scoped discovery, per-run caps draining at 5/run against a 137-event backlog, and — the real defect — **`update_push_event()` increments `attempt_count` on cap-deferrals**, which `pending_push_events()` then filters at `< 3`, so **20 push events have been permanently evicted without a single genuine failure** while `events_deferred` reported them as healthy. The module docstring promises durability the code does not implement. Operator decision: backfill reads the **local clone**, not the API — all 182 SHAs are already on disk, so it costs zero API calls and does not reproduce the rate-limit pressure that caused the caps. 4 phases (backfill → attempt accounting → completeness check in `doctor`/`index_status` → verify against the original CLIO question). Phase 3 exists specifically to end the #155→#157→#169 "one more thing" chain by making completeness continuously derivable rather than discovered by an operator getting a bad answer. **Plan APPROVED by agy relay r2** (r1 Changes requested — 2 Blockers + 3 Shoulds, all accepted; r2 5 `[Pass]` + 1 `[Nit]`, applied). The review added RC5 (`sync_direct_commit_documents()` destroys-then-rebuilds the corpus, so a partial failure shortens it while every upstream measure still reads healthy) and killed a **self-agreeing completeness check**: comparing local git to the local DB would have reported a confident `0` on a stale clone — green through the entire #155→#157 sequence. Phase 3 is now remote-anchored (`git ls-remote` + fetch age) and reports 3 never-netted gaps, with the r2 Nit closed (a row with `path_coverage = ''unavailable''` counts as a gap, not as covered). **No code written yet** — Phase 1 is next. → [GH-169-COMMIT-HISTORY-COVERAGE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-169-COMMIT-HISTORY-COVERAGE.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F62ZYRHNG9QHCZRGM', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Cognee integration path for long-term memory', 'In progress', '11', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-164-COGNEE-INTEGRATION-PLAN.md', NULL, '- **Cognee integration path for long-term memory** ([#164](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/164)) — created 2026-07-19. Dedicated worktree `gh-164-cognee-pdda-spike` cut from `origin/development`; PDDA plan authored and **Phase 0 spike completed**: local Cognee runtime validated (`cognee==1.4.0` in isolated venv), session-memory `remember`→`recall` roundtrip succeeded, and recall output projected into a probe SQLite table (`temp/spikes/gh-164-cognee/spike_results.sqlite`). Graph embedding retries under a dummy key failed with expected `401`, but did not block session recall. **Next:** implement Phase 1 optional `cognee` collector scope with semantic-stage-only projection. → [GH-164-COGNEE-INTEGRATION-PLAN.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-164-COGNEE-INTEGRATION-PLAN.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F4XGDVC5Z8QGSZRBW', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Signal-health nuance — collector panel over-states urgency', 'In progress', '12', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/SIGNAL-HEALTH-NUANCE.md', NULL, '- **Signal-health nuance — collector panel over-states urgency** ([#152](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/152) · [#146](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/146) · [#153](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/153)) — captured 2026-07-18 off the "14 warnings" panel triage. Diagnosed: the collectors are ALIVE; the panel is misreporting. Three root causes cut to three issues — **#152** (the `~/git-pulse-sync` export clone stopped pulling from origin on 2026-07-10, 86 ahead / 1016 behind, freezing every freshness read while collectors scan normally), **#146** (doctor WARNs a running/just-restarted daemon because `_check_launchd` reads the exit-status column, not the live PID, and treats SIGTERM `-15` as a crash), **#153** (segment the flat warning list into notices / warnings / errors so the header count reflects real urgency). Marathon-scoped as 3 phases (p1 #152 `pulse_sync.sh` · p2 #146 `doctor.py` · p3 #153 `doctor.py`+`health.py`, depends on p2) on `marathon/2026-07-18-signal-health`. **DONE — merged 2026-07-19 via PR #158** (corrected 2026-07-21; this line previously said "Next: preflight + run the marathon", stale). Outstanding: confirm the one-time operator reconcile of the live `~/git-pulse-sync` clone (was 86 ahead/1016 behind) actually happened. → [SIGNAL-HEALTH-NUANCE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/SIGNAL-HEALTH-NUANCE.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F0M4X8RYRTAYH8Z11', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Git Pulse Daily Summary false "No git activity found today"', 'In progress', '13', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md', NULL, '- **Git Pulse Daily Summary false "No git activity found today"** ([#129](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/129)) — captured 2026-07-14. Primary fix (day-boundary tz pin) shipped + live-verified 2026-07-14. **Follow-up "no self-heal/clobber" shipped 2026-07-16** via [MARATHON-2026-07-16-B](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md) Lane E (PR #134): a later zero-row rerun can no longer overwrite an earlier real summary from the same day, guarded on both the vault and CLIO upsert paths, 12 new tests. **2 follow-ups remain open:** pull-before-read (deliberately excluded from the marathon — needs an operator design call on git-pull failure handling in a scheduled script) and a tz-invariance regression test for `view.sh` itself. → [GH-129-GITPULSE-DAILY-EMPTY.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GH-129-GITPULSE-DAILY-EMPTY.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FV2YSJA7EHNEDVRY4', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'VS Code extension: native Tree View pane for git-pulse/rebalance device data', 'In progress', '14', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md', NULL, '- **VS Code extension: native Tree View pane for git-pulse/rebalance device data** ([#123](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/123)) — captured 2026-07-09. **Phase 0+1 shipped 2026-07-16** via [MARATHON-2026-07-16-B](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md) Lane C (PR #134): new `vscode-extension/pulse-tree-view/` reads the local rendered pulse markdown (`live-pulse.md`) into a 4-section sidebar Tree View (Today/Yesterday/Upcoming Meetings/Assigned Issues), manual refresh command, 9/9 tests green. No dedicated project doc — full contract lives in the marathon doc''s Lane C section. **Phase 2 (file-watcher live refresh) and Phase 3 (click-through navigation, `.vsix` packaging) remain open**, plus a known dev-only `mocha` transitive advisory worth a version bump. → [MARATHON-2026-07-16-B.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FNGF7DYWMCR7GRY0R', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Source health measures row COUNT, not row QUALITY', 'In progress', '15', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md', NULL, '- **Source health measures row COUNT, not row QUALITY** ([#127](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/127)) — captured 2026-07-14 off the #125 discovery (119/124 dead email rows hid for 3 weeks under an "ok" freshness status). **`content_predicate` shipped 2026-07-16** via [MARATHON-2026-07-16-B](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md) Lane D (PR #134): `_SIGNAL_HEALTH_RULES` in `index_ops.py` now degrades `email`/`github` when >50% of recent rows lack real content (sender/subject, title respectively), registry-driven per the issue''s own suggested seam. Revisited 2026-07-18 as phase `coll-p4-127-health-predicate` of the [collector health bundle](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-18-COLLECTORS/MARATHON.yaml) (PR #147, merged 2026-07-19) — still **deliberately partial**: `email`/`github` are the only 2 sources with a predicate; the other 6 (vault, calendar, sleuth, apple_reminders, figma, ask_self) remain uncovered. No dedicated project doc.', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F7H5NQFQ83DZ95JCY', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Collector health bundle', 'In progress', '16', NULL, NULL, NULL, NULL, NULL, NULL, '- **Collector health bundle** ([#139](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/139) dupe-emitter, [#144](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/144) fan-out client attribution, [#138](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/138) SCHEDULER.md job-liveness) — 4-phase marathon captured/fired 2026-07-18, **DONE — merged 2026-07-19 via PR #147** ("Collector health bundle: #139 #144 #138 #127 #145 (+#141 diagnosed)"). No dedicated project docs — full contracts in the marathon''s phase briefs. #144''s fan-out fix here was client-level request attribution in `_http.py`, not the full request-count reduction #144 originally asked for — real remaining scope there is unscoped (see #144''s own thread). → [MARATHON-2026-07-18-COLLECTORS/MARATHON.yaml](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-18-COLLECTORS/MARATHON.yaml)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F21XYFHD287W4DGR7', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'HiQS — unify all six signals into one ranked pipeline', 'In progress', '17', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-125-HIQS-PIPELINE.md', NULL, '- **HiQS — unify all six signals into one ranked pipeline** ([#125](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/125)) — created 2026-07-14, straight to 2-WORKING. **Supersedes #101, #115, #116, #119** (their docs → `PROJECT/4-MISC/`; shipped code kept, only unfinished scope absorbed). **Phases 0–3 complete.** All six sources (GitHub, vault, Calendar, Sleuth, Gmail, Figma) now feed one bundle that produces one ranked verdict, and `ask()` reads the *same* persisted ranking the what''s-next route writes (first-class `hiqs` field) — the two surfaces can no longer drift. The ranker''s per-source dispatch chain is collapsed into a walk over the collector registry via a new `candidates=` provider, so a seventh source now reaches the ranking by *registering a collector*, proven by a fake-collector test (**Principle 3 discharged** — the headline). Built in Claude Code Cloud, then reviewed and verified locally against real signal data, which surfaced an **upstream Gmail-ingest defect** (119 of 124 email rows are contentless shells — needs its own issue) and a signal-quality hole in the new email arm (fixed + pinned). Net-LOC ≤ 0 was the stated acceptance criterion and was **missed** (+519); recorded as a failed criterion, not restated. **Phase 4 (HiQS surface & brand) next.** → [GH-125-HIQS-PIPELINE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-125-HIQS-PIPELINE.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FR84QG5WQHF8HQZYZ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Auto-promote watched repos to active projects', 'In progress', '18', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-124-AUTO-PROMOTE-WATCHED.md', NULL, '- **Auto-promote watched repos to active projects** ([#124](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/124)) — promoted to 2-WORKING 2026-07-10. **All 3 phases shipped 2026-07-11**: detection + machine-owned write (reusing `github_activity`/`github_commits` operator-identity signals), non-silent surfacing (auth-log alert + repo-pie "New repo added" banner), wired into `_refresh_github()`. Cross-model QA (Codex + agy) found and fixed 2 real blockers (stale-row cleanup cross-contamination; PR-only commit undercounting) plus a name-collision disambiguation gap. **Confirmed live**: the real hourly github-sync job auto-promoted 8 real repos mid-build. Suite 1355 green, doctor clean. Issue left open for operator review/close. → [GH-124-AUTO-PROMOTE-WATCHED.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-124-AUTO-PROMOTE-WATCHED.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FS3HPPHM6QSYEB8BE', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 off-roster reason badge', 'In progress', '19', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-104-FOCUS5-OFFROSTER-REASON.md', NULL, '- **Focus 5 off-roster reason badge** ([#104](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/104)) — promoted to 2-WORKING 2026-07-03. Off-roster "needs attention" strip should surface *why* a repo isn''t in the top-5 — companion to GH-81''s in-roster `explain_recency`/`basis_badge`. **Web slice shipped 2026-07-03**; **macOS Focus5Float desktop parity shipped 2026-07-06** (MARATHON-2026-07-06 Lane C, isolated worktree): finding — the reason string was already on the `/focus-5.json` wire (`focus5_scan.py`), so only the Swift consumer (`OffRosterWarning`/`OffRosterFooter`) needed the change; independently re-verified (`swift build` green). Both desktop + web now done — ready to archive. → [PROJECT/2-WORKING/GH-104-FOCUS5-OFFROSTER-REASON.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-104-FOCUS5-OFFROSTER-REASON.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FA8ETVZVX543GSK9Q', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Adopt gsd-core patterns: hook guard + PDDA conventions + skills inventory + capabilities manifest', 'In progress', '20', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-106-HOOK-GUARD-AND-MANIFEST.md', NULL, '- **Adopt gsd-core patterns: hook guard + PDDA conventions + skills inventory + capabilities manifest** ([#106](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/106)) — promoted to 2-WORKING 2026-07-03. Follow-on build from the closed GSD Core pattern review ([#103](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/103)). **Phase 1 complete**: 6 low-risk/trivially-reversible items landed in one direct pass (not an XYZ marathon — serial anyway, and 2 items shared `PDDA.md` as a target). Corrected mid-build: gsd-core''s own read-before-edit hook explicitly self-disables on Claude Code, so it was substituted for a leaf-ingest bypass guard (`utils/pdda/pdda-leaf-ingest-guard.py`, advisory-only, live-tested). Also landed: a `Verification summary` + `Discuss` phase-loop convention, a subagent/consult hand-back contract, and `SKILLS-INVENTORY.md` (PDDA.md + AGENTS-DOCS.md). `doctor` clean, `pytest` 1264 passed/10 skipped, `pdda.sh run` clean, `CHANGELOG.md` 0.52.0. **Phase 2 (scope-pinned slice) shipped 2026-07-05** (2026-07-05 marathon lane): static `capabilities/manifest.yaml` + generated `capabilities/INDEX.md` for the 3 named high-risk bundles (`relay-xyz`, `xyz`, `consult`), rebalance-side only — the full cross-repo (Rebalance + XYZ) manifest scope remains open. → [GH-106-HOOK-GUARD-AND-MANIFEST.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-106-HOOK-GUARD-AND-MANIFEST.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F2QMN0R51EAQ9T29X', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'XYZ ⇄ Rebalance integration', 'In progress', '21', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-102-XYZ-REBALANCE-INTEGRATION.md', NULL, '- **XYZ ⇄ Rebalance integration** ([#102](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/102)) — promoted to 2-WORKING 2026-07-03 (branch `gh-102-xyz-rebalance-integration`). **Phase 0 discovery run** against XYZ''s GH-75: `XYZ.json` confirmed **completion-only** telemetry (not a per-phase heartbeat), so **#1 reframed** to a "recently-completed sessions" signal — no XYZ-side emitter needed; enumeration source = `registry.tsv` install rows; XYZ already writes atomically. Cross-model consult (Codex + agy) also moved **#3 off direct SQLite** onto a `roadmap_signals.json` projection file (mirror-not-migration). Build order #2→#1→#3→#4. **Phase 1 (seam #2 `xyz-sync check`) next; Phase 2 gated on GH-101.** → [PROJECT/2-WORKING/GH-102-XYZ-REBALANCE-INTEGRATION.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-102-XYZ-REBALANCE-INTEGRATION.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F9QTBWB6944TSQZX2', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Project health axes — concrete spec', 'In progress', '22', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-125-HIQS-PIPELINE.md', NULL, '- **Project health axes — concrete spec** — created 2026-07-07, not yet issue-tracked (`gh_issue: TBA`). A local project-health report scoring a repo on 4–5 high-level axes (UX, stability, security, performance, maintainability). 3 phases planned; no phase fired yet. **Next:** open the GitHub issue so it satisfies the issue-first SOP, then decide whether it sequences behind [#125 HiQS](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/GH-125-HIQS-PIPELINE.md) — a per-repo health score is a candidate *signal*, and HiQS''s Phase 3 `candidates=` provider is the seam it would register against rather than a parallel path. → [REPO-HEALTH-AXES.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/REPO-HEALTH-AXES.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FBH3H1HGK2Z9679S7', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Collector Path and Portability Audit — Phase 6', 'In progress', '23', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/COLLECTOR-PATH-AND-PORTABILITY-AUDIT.md', NULL, '- **Collector Path and Portability Audit — Phase 6** — reopened 2026-06-30 after a Codex review (GH-62) found the original refactor''s Definition of Done was never fully closed. GH-62''s own "High" finding (`dashboard.py` passing a removed `include_semantic` param to `refresh_index()`, runtime `TypeError`) was independently verified already fixed in current code; GH-62 closed with that verification. **4 gaps remain, tracked as the new Phase 6:** (1) not every raw source has one write path, (4) semantic-maintenance CLI `--source all` drifts from the live semantic-stage coverage, (6) `setup_gmail_oauth.py`/`setup_calendar_oauth.py` still hardcode token paths instead of the shared resolver, (8) test/observability blind spots (a mocked-signature test let the dashboard break ship undetected). Phases 0-5 of the original audit are complete and preserved as provenance. → [PROJECT/2-WORKING/COLLECTOR-PATH-AND-PORTABILITY-AUDIT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/COLLECTOR-PATH-AND-PORTABILITY-AUDIT.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FEBMG28MR6969TFBZ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Float — reminders drawer (Apple + Obsidian)', 'In progress', '24', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FOCUS5-REMINDERS-PANEL.md', NULL, '- **Focus 5 Float — reminders drawer (Apple + Obsidian)** — the panel bottom now carries two task sections above the `focus5.md` note: **Apple Reminders** (live EventKit list, explicit label, capped to 8, complete-checkbox write-back) and **Obsidian Reminders** (top 8 open checkboxes from vault-root `0. Goals.md`, exact-line checkbox flip via localhost `GET /focus-5/goals` + `POST /api/focus5/goals/complete`). Load failures are now diagnosable (`vault_not_configured`, `file_missing`, `read_failed`, route/transport/decode errors) instead of a generic banner. **Operator TCC litmus still pending** for the Apple/EventKit side. → [PROJECT/2-WORKING/FOCUS5-REMINDERS-PANEL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FOCUS5-REMINDERS-PANEL.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F7VC6GK8W0MR74J2X', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Repo links open VS Code with "focus-if-open"', 'In progress', '25', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/VSCODE-OPEN-WORKSPACE.md', NULL, '- **Repo links open VS Code with "focus-if-open"** — replace the window-hijacking `vscode://` URI on both surfaces so the card "Open ↗" button focuses an already-open VS Code window (or spawns exactly one). **Both phases code-complete 2026-06-29:** Phase 1 (Mac app `VSCodeLauncher`) + Phase 2 (web `POST /api/focus5/open` — server-side allowlist resolve id→path, direct-argv `code <path>`, two-layer loopback+same-origin guard, `vscode://` fallback). **agy relay QA: Approved (r2/4)** — hardened the local-only guard + `code` binary file-check per its findings; **91 tests passed**. **Next:** operator browser/GUI litmus on both surfaces. → [PROJECT/2-WORKING/VSCODE-OPEN-WORKSPACE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/VSCODE-OPEN-WORKSPACE.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FR5W9GP2KBQS5F09H', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Unified UI refresh + restart (system-wide)', 'In progress', '26', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/UNIFIED-REFRESH-RESTART.md', NULL, '- **Unified UI refresh + restart (system-wide)** — keep the always-on pulse-server as the source-freshness path so no source goes stale and no manual terminal sync is needed. **/ponytail-trimmed to a v1 (2026-06-27)** after a Codex consult QA: the `/api/restart` endpoint + Focus 5 Swift wiring are **deferred**. **v1 = make the existing Refresh button populate the reminders column via the signed EventKit helper (no FDA)** — 3 edits: helper `list-active` op → `/api/refresh` reads it (atomic, last-good-snapshot-wins, ~5s timeout) → column renders. **Phase QA-R remediation shipped 2026-07-01 (PR #100)** — all 7 findings closed, 8 new tests, agy-Approved. **Next:** operator litmus on the live dashboard, then archive. → [PROJECT/2-WORKING/UNIFIED-REFRESH-RESTART.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/UNIFIED-REFRESH-RESTART.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F2CBPWA226XH8R9YD', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Native (standalone Mac App Store track)', 'In progress', '27', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FOCUS-5-APP-STORE.md', NULL, '- **Focus 5 Native (standalone Mac App Store track)** — canonical rewrite plan for a truly standalone macOS app that keeps the Focus 5 UX but removes all runtime dependency on rebalance-OS, Python, localhost JSON, and repo scripts. **Phase 0-R sandboxed re-spike PASSED 2026-07-01** (marathon lane): all 10 QA gates observed in a codesigned App-Sandbox `.app` — `Process`→git empirically blocked, in-process libgit2 returns the full typed fact set, bookmark round-trip verified. Key finding: the SwiftGit2 SPM path is iOS-only, so a macOS-sliced libgit2 is a Phase 2 cost. **Phase 1 next** (freeze native v1 entities). → [PROJECT/2-WORKING/FOCUS-5-APP-STORE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FOCUS-5-APP-STORE.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FY2FGS4G1Q1340NG4', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Float — reference-design UI refresh', 'In progress', '28', NULL, NULL, NULL, NULL, NULL, NULL, '- **Focus 5 Float — reference-design UI refresh** — active as of 2026-07-05 on branch `focus5/floating-panel` in dedicated worktree `.claude/worktrees/focus5-floating-panel`. The new tracked design/implementation doc is [PROJECT/2-WORKING/FOCUS5-UI.html](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FOCUS5-UI.html). First pass keeps the product contract intact while moving the shell toward the RepoMonitor reference: glass panel, icon segmented control, explicit hover affordances, repo-name wrap safety, and refresh-only bottom toast. Swift implementation is in progress. → [PROJECT/2-WORKING/FOCUS5-UI.html](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FOCUS5-UI.html)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FR4P5YBKH1GBBD7TD', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Float — same-session resolution-change resilience', 'In progress', '29', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-2026-07-21/MARATHON.md', NULL, '- **Focus 5 Float — same-session resolution-change resilience** — planned 2026-07-06. The floating panel keeps its autosaved absolute frame across a mid-session display resolution/arrangement change and can strand off-screen, currently recoverable only by rebooting the device. Root cause: `buildPanel()` registers no `didChangeScreenParametersNotification` observer to re-clamp the panel into the new `visibleFrame`. Plan: Phase 1 core re-clamp helper + observer (reboot-free recovery), Phase 2 multi-display/unplug/debounce hardening + geometry self-test. **2026-07-21:** carried forward as p5 of [MARATHON-2026-07-21](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-2026-07-21/MARATHON.md) (Phase 1 only), replacing the never-fired MARATHON-2026-07-07 Lane C it originally belonged to. → [PROJECT/2-WORKING/FOCUS5-RESOLUTION-CHANGE-RESILIENCE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FOCUS5-RESOLUTION-CHANGE-RESILIENCE.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FQH9STMFCBC0EEZTK', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'MARATHON-2026-07-21 bundle', 'In progress', '30', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-2026-07-21/MARATHON.md', NULL, '- **MARATHON-2026-07-21 bundle** ([#8](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/8) tz day-boundary · [#171](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/171) SQLite write-lock · [#167](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/167) semantic backfill gap · [#189](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/189) GH-135 residual gaps) — planned 2026-07-21, **not fired**. Built by a marathon-triage + doc-hygiene pass: 4 disjoint, low-risk Python fixes verified live against current code, chosen from a full open-issue backlog sweep, bundled alongside the carried-forward Focus5Float lane above. No dedicated project docs — full contracts in the marathon''s phase briefs. → [MARATHON-2026-07-21/MARATHON.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/MARATHON-2026-07-21/MARATHON.md)', '2026-09-01T05:02:54Z', '2026-09-01T06:20:45Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FK12HJNPEXP0JVJBY', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'SQLite gateway routing — nine direct-connect bypasses retired behind a CI ratchet', 'Completed', '1', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-136-SQLITE-GATEWAY-ROUTING.md', NULL, '- **SQLite gateway routing — nine direct-connect bypasses retired behind a CI ratchet** ([#136](https://github.com/HiQS-Labs/rebalanceOS/issues/136)) — **DONE 2026-08-30.** Gateway question settled same day (two gateways serve different database files by design — recorded in `ROUTER.md`; the releases ledger is a third self-contained store). 0.76.0 landed the `sqlite3.connect` ratchet in CI (exact per-file baseline, additions and stale shrinks both fail); 0.79.0 routed the eight gateway-eligible sites (five `mode=ro` through `db_connection_readonly`, three `src/` sites through the gateways) and pinned four reasoned `GATEWAY-OK` exemptions (the GH-250 one-shot prod-DB tool, the releases ledger ×3). Baseline ends at `{}` — any new direct connect outside the two gateway directories fails the build. Not to be confused with the archived predecessor''s dashboard-redesign #136. → [GH-136-SQLITE-GATEWAY-ROUTING.md](PROJECT/3-COMPLETED/GH-136-SQLITE-GATEWAY-ROUTING.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F4PWBQE59J0D0X551', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Build 0.73.0 Subsystem Unification', 'Completed', '2', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/BUILD-0.73.0-SUBSYSTEM-UNIFICATION/SCOPE.md', NULL, '- **Build 0.73.0 Subsystem Unification** ([#25](https://github.com/HiQS-Suite/rebalanceOS/issues/25)) — **DONE 2026-08-17**, shipped as 0.73.0 "Subsystem Unification" (PR [#40](https://github.com/HiQS-Suite/rebalanceOS/pull/40)). All six marathon phases landed: HiQS test-process isolation (#7), timestamp handling through the shared time helper (#25), every GitHub API call through the one authenticated client (#26), deduplicated database persistence and connection helpers (#27), a single git subprocess wrapper (#28), and dead-code / stale-doc removal (#30). Behaviour is unchanged for operators; what changed is that a fix to any shared primitive now lands everywhere at once. Two lint regressions the marathon introduced (an unused import pair and two unformatted modules) were caught and fixed at merge time — the phase gates ran the test suite but not the repo''s lint gate, which is worth wiring into the pre-advance command next time. → [SCOPE.md](PROJECT/3-COMPLETED/BUILD-0.73.0-SUBSYSTEM-UNIFICATION/SCOPE.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FPYQD3CZWZCSYRMFK', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'github_embeddings vector bloat — reclaim, backfill, re-embed', 'Completed', '3', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-250-VECTOR-BLOAT/SCOPE.md', NULL, '- **github_embeddings vector bloat — reclaim, backfill, re-embed** ([#250](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/250)) — **DONE 2026-08-14**, shipped as 0.69.0 "Reclaim" (merged in `55206f34`). 2,678,350 orphaned vectors deleted and the store rebuilt 14.62 GB → 3.96 GB, with the live vector count identical at 32,908 before and after — the assertion that proves only garbage went. Both `doctor` orphan invariants flipped FAIL → OK (github and semantic); R5 embedded 6,757 documents at a 2.35 GB MLX peak. **R1 was waived by the operator** for wall clock rather than passed, then vindicated when a full sync on 2026-08-15 produced zero new orphans. The lasting finding is not the 10.8 GB: **four safety mechanisms in a runbook marked "complete and verified" were broken**, each having passed prior review, because rehearsals ran against fixtures and the happy path rather than the live fleet — a fence pointed at a stale repo-root database, a roster covering 5 of 11 loaded jobs, a pause assertion testing for a string paused jobs never print, and `three_eyes pause` not stopping launchd at all ([#272](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/272), which reaches well beyond this effort). → [SCOPE.md](PROJECT/3-COMPLETED/GH-250-VECTOR-BLOAT/SCOPE.md) · [RECLAIM-RUNBOOK.md](PROJECT/3-COMPLETED/GH-250-VECTOR-BLOAT/RECLAIM-RUNBOOK.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F7XSQ2SF730BN2HYK', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Hard kernel panic — unbounded concurrent embedding runs', 'Completed', '4', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-172-EMBEDDING-JOB-GUARD.md', NULL, '- **Hard kernel panic — unbounded concurrent embedding runs** ([#172](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/172)) — **DONE 2026-07-20** via PR #174 (guard built) + PR #181 (guard wired). Three Python embedding runs stacked to ~90 GB resident on a 68.7 GB machine, saturating the VM compressor until `watchdogd` starved for 90s and the kernel panicked. Attribution took a correction: the first RCA blamed the ask_self stack, but ask_self is Gemini/768 and had not run since 2026-07-02 — the culprit is the HiQS signal path (`embedder.py`, Qwen3 via MLX), which commits per batch and so left no disk trace. Fixed with a `flock` single-instance lock plus an in-process memory ceiling, applied at the **library leaves** (`embed_chunks`, `embed_pending`) rather than the launchd wrappers, because the causing run was agent-spawned. 16 tests; zero regressions; `pdda.sh run` clean. → [GH-172-EMBEDDING-JOB-GUARD.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-172-EMBEDDING-JOB-GUARD.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F4RNPXS9A2WQSW77D', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Audit: no launchd job declares a memory limit, nice value, or single-instance lock', 'Completed', '5', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-175-LAUNCHD-FLEET-HARDENING.md', NULL, '- **Audit: no launchd job declares a memory limit, nice value, or single-instance lock** ([#175](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/175)) — **DONE 2026-07-20** via PR #181 (item 1) + PR #182 (items 3/4/5). Device audit prompted by #172; found the unbounded posture was fleet-wide across 37 plists, not specific to embedding. Shipped: per-job peak-RSS logging to `temp/logs/job_rss.jsonl` so the next incident is attributable to a job rather than anonymous `Python`; `Nice=5` on the five batch jobs; and a fully de-collided schedule (no two jobs share a slot). Item 2 (`HardResourceLimits`) **struck** — `RLIMIT_RSS` is defined but unenforced on Darwin, so it would have produced jobs that look bounded and are not. Finding 6 (three silently failing jobs) fixed as device config, no repo diff. → [GH-175-LAUNCHD-FLEET-HARDENING.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-175-LAUNCHD-FLEET-HARDENING.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F0855G97G26F3DPRF', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus5Float telemetry viewer: .md support', 'Completed', '6', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md', NULL, '- **Focus5Float telemetry viewer: .md support** ([#121](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/121)) — **DONE 2026-07-16.** Base `.md` viewer (picker, kind discriminator, symmetric state clear, GFM tables) shipped 2026-07-15; size ceiling closed via MARATHON-2026-07-16 Lane B (PR #133); **Phase 2 (header/status kind label, self-test discriminator) closed via [MARATHON-2026-07-16-B](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md) Lane B (PR #134)** — both phases now fully shipped and merged. → [GH-121-FOCUS5-TELEMETRY-MD-VIEWER.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-121-FOCUS5-TELEMETRY-MD-VIEWER.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F99RP2HWGDTMPFEWJ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Architecture diagram: show incoming (not-yet-active) XYZ HQ data', 'Completed', '7', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md', NULL, '- **Architecture diagram: show incoming (not-yet-active) XYZ HQ data** ([#120](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/120)) — **DONE 2026-07-16** via [MARATHON-2026-07-16-B](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/MARATHON-2026-07-16-B.md) Lane A (PR #134). Staged `xyz_hq` + `xyz_disposition_collector` nodes added to both `system-diagram.json` and the inlined `system-diagram.html` spec, dashed/`(planned)` not-active convention, verified byte-identical between the two specs. Originally queued into MARATHON-2026-07-07 Lane B, which never fired — the 2026-07-16 GH-issue triage sweep re-picked this issue up independently. → [GH-120-DIAGRAM-XYZ-INCOMING.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-120-DIAGRAM-XYZ-INCOMING.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FSW09HTH4X2W5FKTZ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'daily-sync fails daily — "database is locked" from collision with hourly github-sync', 'Completed', '8', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-131-DAILY-SYNC-GITHUB-LOCK.md', NULL, '- **daily-sync fails daily — "database is locked" from collision with hourly github-sync** ([#131](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/131)) — **DONE 2026-07-16** via MARATHON-2026-07-16 Lane A. Root cause: `com.rebalance-os.daily-sync` (06:30 daily) collides with the hourly `com.rebalance-os.github-sync` job (fires :45), both writing `rebalance.db`''s github tables concurrently. Correction mid-build: `db_connection()` already sets a 30s `busy_timeout` globally, so the gap was a scope-level retry, not a missing pragma — a new `_retry_on_db_locked()` wraps `_github_adapter`, retrying the whole (idempotent) github-scope refresh up to 3x with linear backoff, re-raising if the lock never clears. 6 new tests; suite green; doctor clean; `pdda.sh run` clean. Merged to `development` via PR #133. → [GH-131-DAILY-SYNC-GITHUB-LOCK.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-131-DAILY-SYNC-GITHUB-LOCK.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FTM58FDAN8TDG8JFR', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Centralize UTC→local time display', 'Completed', '9', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-130-CENTRALIZE-LOCAL-TIME-DISPLAY.md', NULL, '- **Centralize UTC→local time display** ([#130](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/130)) — **DONE 2026-07-16.** `format_local()`/`format_relative()` added to `tz_utils.py` (29 new tests, closing its zero-coverage gap); all 5 ad-hoc call sites migrated behavior-preserving; `cli/semantic.py`''s `rebalance semantic-query` now shows `Local Time: …` instead of a bare unlabeled UTC stamp. relay-xyz (Codex) round 1 found 1 gap (missing DST-boundary test), fixed same session; round 2 **Approved**. Merged to `development` via PR #132. → [GH-130-CENTRALIZE-LOCAL-TIME-DISPLAY.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-130-CENTRALIZE-LOCAL-TIME-DISPLAY.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F0Y8CD4FFQB1KHCAT', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Obsidian Vault Daily Activity Sync', 'Completed', '10', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-112-OBSIDIAN-DAILY-SYNC.md', NULL, '- **Obsidian Vault Daily Activity Sync** ([#112](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/112)) — **DONE 2026-07-04.** Ran and shipped in one sequential session (see the archived `MARATHON-2026-07-04.md`): all phases, launchd job installed and live at 18:00 daily. → [GH-112-OBSIDIAN-DAILY-SYNC.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-112-OBSIDIAN-DAILY-SYNC.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FVD5S716M1G7MHZDY', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Multi-device Git Pulse daily synthesis → Obsidian vault', 'Completed', '11', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-114-GIT-PULSE-DAILY-SYNTHESIS.md', NULL, '- **Multi-device Git Pulse daily synthesis → Obsidian vault** ([#114](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/114)) — **DONE 2026-07-05.** Shells out to `view.sh --today` (existing multi-device aggregation layer) → Gemini synthesis → sentinel block in `0. Today''s Notes.md`. → [GH-114-GIT-PULSE-DAILY-SYNTHESIS.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-114-GIT-PULSE-DAILY-SYNTHESIS.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F73C8H8GGT1ZERVV5', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'focus5 refresh worktree-drop + repo-name font shrink', 'Completed', '12', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-109-FOCUS5-APP-REFRESH-BUTTON.md', NULL, '- **focus5 refresh worktree-drop + repo-name font shrink** ([PR #111](https://github.com/Hypercart-Dev-Tools/rebalance-OS/pull/111), [#109](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/109), [#110](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/110)) — **DONE 2026-07-04.** `summarize_focus5` now filters out repos whose on-disk path/`.git` no longer exists on the read path (`drop_missing_paths=True`), so the Mac app''s refresh drops a deleted worktree without a full rescan; repo-name font shrunk ~20% (Mac app 17pt→14pt, HTML 15px→12px). Both visually verified live in the native Focus5Float app (worktree create→sync→delete→refresh round-trip; font legibility screenshot), not just the Python suite (153 passed). `/Applications/Focus 5 Float.app` rebuilt via `make-app.sh`. → [GH-109-FOCUS5-APP-REFRESH-BUTTON.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-109-FOCUS5-APP-REFRESH-BUTTON.md) · [GH-110-FOCUS5-APP-SHRINK-REPO.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-110-FOCUS5-APP-SHRINK-REPO.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FW91ZE5D5RE16WBW7', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'GSD Core pattern review', 'Completed', '13', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-103-GSD-CORE-PATTERN-REVIEW.md', NULL, '- **GSD Core pattern review** ([#103](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/103)) — **DONE 2026-07-03.** Reviewed the MIT `gsd-core` framework for reusable patterns across XYZ (vendored) + Rebalance native, scoped to two families (phase-loop/context-engineering, skill/command/hook/agent architecture). All 4 phases run via `consult` (Codex + agy in parallel, not Claude subagents). Top-3 adopt calls (ranked by ROI, one deliberate override flagged): (1) a verify-before-done PDDA record, (2) a read-before-edit + blocking hook guard, (3) a narrow `capabilities/`-style manifest (scoped specifically to survive a real YAGNI objection one advisor raised) — XYZ had zero unique adopt items, only shared-with-Reb ones. One real cross-model fabrication caught and adjudicated in Phase 0 (agy invented out-of-bounds citations against a gitignored vendored dir). Next actions (a PDDA edit, a GH issue, and a ROADMAP-parked capture doc) are the operator''s call, not executed here. → [PROJECT/3-COMPLETED/GH-103-GSD-CORE-PATTERN-REVIEW.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-103-GSD-CORE-PATTERN-REVIEW.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FPKVX4187J4PWH6MG', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 newest-dirty-repo banner', 'Completed', '14', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-105-FOCUS5-DIRTY-BANNER.md', NULL, '- **Focus 5 newest-dirty-repo banner** ([PR #107](https://github.com/Hypercart-Dev-Tools/rebalance-OS/pull/107), [#105](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/105)) — **DONE 2026-07-03.** Slim single-row banner above card #1 on the default Focus 5 view naming the single most-recently-touched dirty repo (`my_local_commit_ts`-ranked); informational only, no change to top-5 ranking. Backend (`focus5_scan.py`/`web.py`) + macOS Focus5Float parity (`CONTRACT.md`, `Models.swift`, new `DirtyBannerView`) both shipped; suite green (1271 passed), `rebalance doctor` clean, 4 Swift self-test flavors OK, installed to `/Applications`. → [PROJECT/3-COMPLETED/GH-105-FOCUS5-DIRTY-BANNER.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-105-FOCUS5-DIRTY-BANNER.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FTK25H2006E29YEGF', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Client auto-discovery', 'Completed', '15', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/CLIENT-AUTO-DISCOVERY.md', NULL, '- **Client auto-discovery** ([PR #100](https://github.com/Hypercart-Dev-Tools/rebalance-OS/pull/100)) — **DONE 2026-07-01.** Owner-as-client deterministic spine (Phase 1, 2026-06-30) plus a code-complete Gemini gap-fill (Phase 2) for `None`-client projects, batched call, fail-soft. Phase 2 kill-check measured live registry coverage: 15/15 active projects (100%) already owner-as-client labeled, so the kill switch fired (≥90% threshold) — Gemini gap-fill ships dormant, never exercised against a live key, re-activates automatically if a calendar-only/personal-account project appears. No new table/lifecycle/MCP tool. 9 tests (`test_client_buckets.py` + `test_client_gapfill.py`); suite green. → [PROJECT/3-COMPLETED/CLIENT-AUTO-DISCOVERY.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/CLIENT-AUTO-DISCOVERY.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FS90DQ1VBWK4YE9AF', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Watch-list coverage guard', 'Completed', '16', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/WATCHLIST-COVERAGE-GUARD.md', NULL, '- **Watch-list coverage guard** ([PR #82](https://github.com/Hypercart-Dev-Tools/rebalance-OS/pull/82)) — **DONE 2026-06-30 (PR #82 merged).** Canonical watched-repos snapshot + silent-reduction alarm: additive migration `0009` + isolated `watchlist_guard.py` (`classify_removal` + `snapshot_and_detect` single writer) at the end of `_refresh_github` (clean-sync only) + `_EVENT_BADGE` ⚠ chip on `/auth-log`. 11 guard tests; suite green; doctor clean; live baseline 59 watched / 24 durable-intent. → [PROJECT/3-COMPLETED/WATCHLIST-COVERAGE-GUARD.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/WATCHLIST-COVERAGE-GUARD.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F37HZKQ0DCK7CK77R', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '96', 'GH-96 git-pulse stages PDDA registry projection', 'Completed', '17', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-96-GITPULSE-STAGE-PDDA-PROJECTION.md', NULL, '- **GH-96 git-pulse stages PDDA registry projection** ([#96](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/96)) — **DONE 2026-06-30.** The git-pulse collector staged `pulse-<device>.md` + `devices/<device>.yaml` but not the PDDA projection `pdda/registry-<device>.tsv`, so on PDDA-installed devices it stayed untracked and never synced (sync-side half of the multi-device rollup; write-side was `pdda#7`). Added a guarded `append_stage_path "pdda/registry-$device_id.tsv"` before `git add`. New collector staging test (5/5); doctor clean; suite 1242 green; merged to `development` via PR #97. → [PROJECT/3-COMPLETED/GH-96-GITPULSE-STAGE-PDDA-PROJECTION.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-96-GITPULSE-STAGE-PDDA-PROJECTION.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FAE0CFZ5GW3Z8JNKD', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '94', 'GH-94 priority_tier soft down-weight', 'Completed', '18', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-94-PRIORITY-DOWNWEIGHT.md', NULL, '- **GH-94 priority_tier soft down-weight** ([#94](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/94)) — **DONE 2026-06-30.** `priority_tier` now reaches the "what to do next" ranking (previously dashboard-only): low-cadence projects (tier ≥ 4, e.g. weekly devops repos) get a `[priority:low]` prompt tag + down-weight lever and sink in the deterministic fallback — soft down-weight, not a mute. One shared `_is_low_priority` predicate; reuses the existing priority-rule config; Focus 5 + `NOISE_REPOS` untouched. 4 tests; suite 1230 green; doctor clean. → [PROJECT/3-COMPLETED/GH-94-PRIORITY-DOWNWEIGHT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-94-PRIORITY-DOWNWEIGHT.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FRZH27T07XG3VHS7D', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '93', 'GH-93 MCP probe tools', 'Completed', '19', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-93-MCP-PROBE-TOOLS.md', NULL, '- **GH-93 MCP probe tools** ([#93](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/93)) — **DONE 2026-06-30.** Two read-only MCP tools so a client (Claude Desktop) can probe **both** raw source rows and the synthesized headline: `peek_source(source, limit)` (allowlist-guarded, 7 source tables, no free-form SQL) + `get_next_actions()` (reads persisted ranking, no recompute, None-safe). Folded into `index.py` + `manifest.json`; 4 tests; suite 1226 green, doctor clean. → [PROJECT/3-COMPLETED/GH-93-MCP-PROBE-TOOLS.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-93-MCP-PROBE-TOOLS.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FYGN851PPN0VKGYCY', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Gemini "What to do next" → fixed vault file', 'Completed', '20', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GEMINI-WHATS-NEXT-VAULT.md', NULL, '- **Gemini "What to do next" → fixed vault file** — **DONE 2026-06-29.** The daily "what to do next" is now genuinely Gemini-synthesized: paid-key **file** resolver added to `get_gemini_api_key()` (env/config/`~/secrets/gemini-paid-key.txt`, multi-line aware) **and** the retired `gemini-2.0-flash` default swapped to `gemini-2.5-flash` (root cause — the dead model, not just a missing key, was forcing the Qwen-0.6B fallback that emitted `<rank>. <title>` placeholders); parser now rejects placeholder echoes. The same ranked output renders to the fixed vault file `Dashboards/What To Do Next.md` via a precompute-hook sink. Live-verified (`model_used=gemini-2.5-flash`, 0 placeholder titles); suite 1202 green, doctor passed. → [PROJECT/1-INBOX/GEMINI-WHATS-NEXT-VAULT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/1-INBOX/GEMINI-WHATS-NEXT-VAULT.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F790AXE683P4V2J00', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Apple Reminders unified integration', 'Completed', '21', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/APPLE-REMINDERS-UNIFIED-PLAN.md', NULL, '- **Apple Reminders unified integration** — read-only `apple_reminders` SQLite collector **plus** an EventKit write surface, both **shipped + live-verified (2026-06-27)**. Phases 0–4: deterministic store discovery, WAL-safe snapshot extractor (`src/rebalance/ingest/apple_reminders.py`), dynamic REMCD mapper, collector registration in `index_ops.py` + reconcile-don''t-delete storage, read accessor + pulse "Today" column, schema-drift health. Phase 5: signed LaunchServices helper performs EventKit create/update/complete/delete via `rebalance apple-reminders` (dry-run default, `request_id` idempotency, write serialization, three-state audit); **57 tests green**, full CRUD proven live. **Phase 6 dashboard write-back v1 SHIPPED (2026-06-30):** the pulse column is now actionable — a per-reminder complete check POSTs `/api/apple-reminders/complete` through the Phase 5.1 orchestrator (single-writer + audit; optimistic grey-out; `create`/`delete` stay CLI-only); **5 endpoint regression tests** added. Deferred by choice: cross-version validation (2nd Mac), snapshot perf, notes/sections decode, auto-refresh of the column after a write (FDA-gated reconcile). → [PROJECT/2-WORKING/APPLE-REMINDERS-UNIFIED-PLAN.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/APPLE-REMINDERS-UNIFIED-PLAN.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FDN3J5NPRKBBA3EG0', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Float (floating macOS card stack)', 'Completed', '22', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P2-MACOS-FOCUS5-FLOAT.md', NULL, '- **Focus 5 Float (floating macOS card stack)** — native menu-bar app rendering the Focus 5 roster as a collapsible card stack over live `GET /focus-5.json`. **All phases 0–5 done** (frozen contract + 90 tests, `Focus5Float` SwiftPM package, floating `NSPanel`, `Focus5Client` live data, collapsible card UI, packaged `/Applications` app + launch-at-login + roster-health light) plus a post-1.0 read-only bottom-note from vault `focus5.md`. Ready to move to `3-COMPLETED` once the `.icns` artwork lands. → [PROJECT/2-WORKING/P2-MACOS-FOCUS5-FLOAT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P2-MACOS-FOCUS5-FLOAT.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F81CFTZ58C3WDSZSS', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Float — Telemetry tab', 'Completed', '23', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P2-FOCUS5-TELEMETRY-TAB.md', NULL, '- **Focus 5 Float — Telemetry tab** — third tab reading health-annotated JSON from `~/Documents/telemetry/`; `ViewMode` enum + orange-capable `HealthDot` + reader/model/view all shipped through Phase 2 (explicit file selection + visible decode errors). `swift build` green, `FOCUS5_SELFTEST` passes. **Operator litmus pending** (eyeball 3 demo rows), then archive. → [PROJECT/2-WORKING/P2-FOCUS5-TELEMETRY-TAB.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P2-FOCUS5-TELEMETRY-TAB.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F0RF9SDA0330WSA7H', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'CLIO migration + Focus 5 Float — Prompt Log tab', 'Completed', '24', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P2-FOCUS5-CLIO-PROMPT-LOG-TAB.md', NULL, '- **CLIO migration + Focus 5 Float — Prompt Log tab** — created 2026-07-17. **Phase 0 (CLIO migration) DONE:** pulled the append+cursor exporter + hardening fixes from upstream `CLIO-Claude-Prompts@ef96a44` into `utils/CLIO/` as its new canonical home (commit `cfeafe4`); re-installed and smoke-tested on this Mac Studio. **Phase 1 (fifth Focus5Float tab) next:** reads the CLIO-rendered Obsidian Markdown as 1:1 source-of-truth, newest-first feed, up to 5 FIFO-pinned entries as a persistent "what I actually started" anchor above the scrollable feed. → [PROJECT/2-WORKING/P2-FOCUS5-CLIO-PROMPT-LOG-TAB.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P2-FOCUS5-CLIO-PROMPT-LOG-TAB.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F777VD8BEQ6T11J3G', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 Float — offline cache & manual server start', 'Completed', '25', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P3-FOCUS5-FLOAT-OFFLINE-RESILIENCE.md', NULL, '- **Focus 5 Float — offline cache & manual server start** — resilience follow-on: offline roster cache (instant cold-start, "cached · {age}") + one-click "Start server" (detached `Process`, login-shell binary resolution, poll-until-healthy). Both phases built, `swift build` green, binary-resolution root-caused (`pipx install -e .` → `~/.local/bin/rebalance`), app icon shipped. **Operator litmus pending.** → [PROJECT/2-WORKING/P3-FOCUS5-FLOAT-OFFLINE-RESILIENCE.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/P3-FOCUS5-FLOAT-OFFLINE-RESILIENCE.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FV0Y2EC89RA32VK29', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 — identity-agnostic ranking vector', 'Completed', '26', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-81-FOCUS5-RANK-VECTOR.md', NULL, '- **Focus 5 — identity-agnostic ranking vector** ([GH-81](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/81)) — the headline board silently dropped repos whose recent local commits used a different author email. **Phases 1 & 2 complete (2026-06-24):** `rank_recent_activity` now ranks on local-commit reflog recency (`my_local_commit_ts` + recorded `recency_basis` fallback ladder, migration `0007`), and the off-roster strip + card badges explain *why* each repo ranks (recency vs the #5 cutoff, fallback basis shown). Suite green (1109); real-device proof = 24 repos no longer silently dropped. → [PROJECT/3-COMPLETED/GH-81-FOCUS5-RANK-VECTOR.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/GH-81-FOCUS5-RANK-VECTOR.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F25DP8KASQ46ADV8E', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Focus 5 active repos bug remediation', 'Completed', '27', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/FOCUS-5-RANKING-BUG-AND-REMEDIATION.md', NULL, '- **Focus 5 active repos bug remediation** — root-cause trace + remediation implemented, tested, and verified live (transient Dirty Five mode, scan-root CLI setters); Phase 3 activated 2026-06-24 (`com.rebalance-os.github-sync` installed + firing hourly). → [PROJECT/3-COMPLETED/FOCUS-5-RANKING-BUG-AND-REMEDIATION.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/3-COMPLETED/FOCUS-5-RANKING-BUG-AND-REMEDIATION.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F1SV993N3HS6D7BTV', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Team Calendar as a Signal (HiQS)', 'Completed', '28', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/SIGNAL-GENERATION/P2-TEAM-CALENDAR-SIGNAL.md', NULL, '- **Team Calendar as a Signal (HiQS)** — Phase 2 v0.5 built on `development`, data-layer DoD proven, pending live validation and merge/tag. → [PROJECT/2-WORKING/SIGNAL-GENERATION/P2-TEAM-CALENDAR-SIGNAL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/SIGNAL-GENERATION/P2-TEAM-CALENDAR-SIGNAL.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FK391Q9Y2QA8W22AE', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Unified front-door, portability & auth hardening', 'Completed', '29', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FRONT-DOOR-PORTABILITY-AUTH-UNIFICATION.md', NULL, '- **Unified front-door, portability & auth hardening** — Phases 1–6 complete, merged to `development` (v0.41.1, PR #78). Operator-only per-machine `migrate-secrets` (~2 Macs) + deferred fleet/multi-operator scope remain; `development` → `main` PR pending. → [PROJECT/2-WORKING/FRONT-DOOR-PORTABILITY-AUTH-UNIFICATION.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/2-WORKING/FRONT-DOOR-PORTABILITY-AUTH-UNIFICATION.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FS43VCM5SN8N3JVEQ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'AI-agent front door (ROUTER.md)', 'Completed', '30', NULL, NULL, NULL, NULL, NULL, NULL, '- **AI-agent front door (ROUTER.md)** — added the canonical startup-order entry point (ROUTER → AGENTS → ARCHITECTURE → ROADMAP → PROJECT docs; run `rebalance doctor` / `pytest tests/` / `utils/pdda-run.sh` before claiming wins), completing the PDDA front-door layer alongside the installed `utils/pdda-*.sh` suite. → [ROUTER.md](ROUTER.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FYXD84059F7M9QPG0', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Fused retrieval measurement — PAUSED by operator decision 2026-08-20, do not restart unasked', 'Deferred · vision', '1', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-94-FUSED-RETRIEVAL-PROTOCOL.md', NULL, '- **Fused retrieval measurement — PAUSED by operator decision 2026-08-20, do not restart unasked** ([#94](https://github.com/HiQS-Suite/rebalanceOS/issues/94)) — GH-81 measured the embedding lanes in isolation, but production fuses vector + FTS5 via RRF, so the end-to-end number was never produced. A protocol was written and independently reviewed (Codex + agy); review showed the primary test is **unrunnable on the existing query set** — only 5 of 39 queries can move the fused result, and n=5 cannot reach significance under any outcome. Closing that gap needs ~25 new hand-built lexical-hard queries. **The operator declined that cost: retrieval quality is judged by everyday use instead.** BGE-small, the query prefix, and hybrid RRF (k=60) are settled and not under review — BGE beats Qwen3-0.6B on this corpus overall (0.7507 vs 0.6049 MRR@10) and by ~2x on the lexical-hard slice (0.600 vs 0.329), at 3x lower query latency and 384 vs 1024 dimensions. A third reviewer (Codex) approved the pause but cautioned that the 25-of-39 FTS5 result does **not** prove low headroom — the query set is plausibly biased toward keyword-friendly tasks, and on lexical-hard queries FTS5 scores 0.0 while the vector index carries the entire load. Reopen only on a concrete retrieval failure traced to ranking — not to ingest, coverage, or a stale index. → [GH-94-FUSED-RETRIEVAL-PROTOCOL.md](PROJECT/2-WORKING/GH-94-FUSED-RETRIEVAL-PROTOCOL.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F8NQ7C0CBTQ8CFSX8', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Signal-quality contract (observe-first source health)', 'Superseded', '1', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-101-SIGNAL-QUALITY-CONTRACT.md', NULL, '- **Signal-quality contract (observe-first source health)** ([#101](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/101)) — **superseded 2026-07-14 by #125.** Kept: Ph1–2 (`recent_row_count_7d` on all 8 sources, freshness `status`/`reason`, doctor warnings). Absorbed: the kill-gated Ph3 → #125 Phase 3 verdict. → [PROJECT/4-MISC/GH-101-SIGNAL-QUALITY-CONTRACT.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-101-SIGNAL-QUALITY-CONTRACT.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FCH24VYH9X6PCP1MZ', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Zapier ingest: alternative email & calendar streams', 'Superseded', '2', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-115-ZAPIER-INGEST.md', NULL, '- **Zapier ingest: alternative email & calendar streams** ([#115](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/115)) — **superseded 2026-07-14 by #125.** Kept: Ph1 webhook receiver (`POST /api/zapier/ingest` + auth). Absorbed: Ph2–3 (email/calendar via Zapier) → #125 Phase 3 defer/kill — native OAuth already supplies both (124 emails, 1573 events), so a second ingest path for signals we already have is speculative. → [PROJECT/4-MISC/GH-115-ZAPIER-INGEST.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-115-ZAPIER-INGEST.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7FT7VS9S55GKBRW2TD', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Cross-day velocity / unfinished-work signal', 'Superseded', '3', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-116-VELOCITY-SIGNAL.md', NULL, '- **Cross-day velocity / unfinished-work signal** ([#116](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/116)) — **superseded 2026-07-14 by #125.** Kept: Ph1 (`compute_deep_work_signals()`, doctor "deep work" line). Absorbed: Ph2 (fold into `rank_next_actions`) → #125 Phase 3, where it becomes a candidate arm on the unified bundle rather than a parallel signal. → [PROJECT/4-MISC/GH-116-VELOCITY-SIGNAL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-116-VELOCITY-SIGNAL.md)', '2026-09-01T05:02:54Z', '2026-09-01T05:02:54Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DNJK7F6MH7HVAS7F93G844', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'HiQS marketing label', 'Superseded', '4', NULL, NULL, NULL, NULL, 'PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-119-HIQS-LABEL.md', NULL, '- **HiQS marketing label** ([#119](https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/119)) — **superseded 2026-07-14 by #125.** Nothing had fired. Rescoped: HiQS is no longer a label applied *to* the signal — it **is** the unified pipeline. Brand pass → #125 Phase 4. → [PROJECT/4-MISC/GH-119-HIQS-LABEL.md](PROJECT/4-MISC/ARCHIVED-PREDECESSOR/4-MISC/GH-119-HIQS-LABEL.md)
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1DT14ZG8BPPAF5Z6SBJ13QX', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'CLIO prompt logs ingestion into RebalanceOS semantic index', 'In progress', '1', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-141-CLIO-INGEST.md', NULL, '- **CLIO prompt logs ingestion into RebalanceOS semantic index** ([#141](https://github.com/HiQS-Labs/rebalanceOS/issues/141)) — opened 2026-08-31. Ingest CLIO prompts from ~/.claude/prompt-log.jsonl to RebalanceOS semantic index via index_ops.py. Use prompt extraction and PR/Issue heuristic matching. → [GH-141-CLIO-INGEST.md](PROJECT/3-COMPLETED/GH-141-CLIO-INGEST.md)', '2026-09-01T06:20:45Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1J1STG7A2374VW5RQ7TGNW3', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', NULL, 'Activity-signal read-layer consolidation', 'Queue / parked intake', '1', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-150-ACTIVITY-SIGNAL-CONSOLIDATION.md', NULL, '- **Activity-signal read-layer consolidation** ([#150](https://github.com/HiQS-Labs/rebalanceOS/issues/150)) — queued 2026-09-02 from the #147 follow-up audit. Ingest is already one pipeline; the read side is not: 7 alias-blind aggregation surfaces (same org-mirror defect class as #147), two Gemini REST clients, 5+ day-window implementations, 3 commit-counting semantics, and a duplicated Claude Cloud signal. Extends 0.75.0 fe1''s `db/queries.py` with the canonical repo identity as the mandatory key. → [GH-150-ACTIVITY-SIGNAL-CONSOLIDATION.md](PROJECT/1-INBOX/GH-150-ACTIVITY-SIGNAL-CONSOLIDATION.md)', '2026-09-02T21:53:31Z', '2026-09-02T21:53:31Z', NULL, NULL, NULL, NULL, NULL);
